async function getMemberDashboard(token:string){const s=await sessionFromToken(token);if(s.role!=='MEMBER')throw new Error('Member portal only.');const p:any=await getMemberProfile(token,s.memberId);const notifications=upperRows(await many(T.NOTIFICATIONS,{member_id:s.memberId},10,'created_at'));const start=await societyStart();const dueItems=upperRows((await many(T.MONTHLY_DUES,{member_id:s.memberId},500,'due_month')).filter((d:A)=>asStatus(d.status)!=='MERGED'&&num(d.balance)>0&&String(d.due_month)>=start&&String(d.due_month)<=monthKey()));let schedules:A[]=[];for(const l of p.loans.filter((l:A)=>['DISBURSED','ACTIVE','OVERDUE'].includes(l.STATUS)))schedules.push(...await many(T.LOAN_SCHEDULE,{loan_id:l.LOAN_ID},500));schedules=schedules.filter(x=>x.status!=='PAID').sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date)));return {member:{memberId:p.member.MEMBER_ID,name:p.member.NAME_BN||p.member.NAME_EN,status:p.member.STATUS,joinDate:p.member.JOIN_DATE,photoFileId:p.member.PHOTO_FILE_ID},summary:{savings:p.savingsBalance,due:p.dueBalance,units:p.unit?num(p.unit.UNITS):0,monthlyAmount:p.unit?num(p.unit.UNITS)*num(p.unit.UNIT_AMOUNT):0,loanOutstanding:p.loanOutstanding,nextLoanDue:schedules[0]?.due_date||''},recentTransactions:p.transactions.slice(0,8),notifications,dueItems:dueItems.slice(0,12)}}

async function generateMonthlyDues(token:string,m:string){const s=await sessionFromToken(token);requirePerm(s,'savings.collect');m=String(m||monthKey()).slice(0,7);if(m<await societyStart())throw new Error('সমিতির মাসিক হিসাব '+await societyStart()+' থেকে শুরু।');if(m>monthKey())throw new Error('ভবিষ্যৎ মাসের Due আগে থেকে Generate করা হবে না। ভবিষ্যৎ মাসের টাকা দিতে মাসিক জমা থেকে ওই মাস নির্বাচন করুন।');return rpc('nd_generate_monthly_dues',{p_user_id:s.userId,p_month:m})}
async function changeSavingsUnits(token:string,memberId:string,units:A,effectiveFrom:A,reason=''){const s=await sessionFromToken(token);requirePerm(s,'members.edit');return rpc('nd_change_savings_units',{p_user_id:s.userId,p_member_id:memberId,p_units:Math.max(1,Math.floor(num(units))),p_effective_from:dateOnly(effectiveFrom||today()),p_reason:reason||''})}
async function getSavingsPage(token:string,options:A={}){const s=await sessionFromToken(token);if(s.role==='MEMBER'){const memberId=s.memberId;const dues=upperRows(desc((await many(T.MONTHLY_DUES,{member_id:memberId},2000)).filter((d:A)=>asStatus(d.status)!=='MERGED'),'due_month'));const tx=upperRows(desc((await many(T.TRANSACTIONS,{member_id:memberId},1000)).filter((t:A)=>t.category==='SAVINGS'),'txn_date').slice(0,100));return {memberId,unit:await currentUnit(memberId),savingsBalance:await memberSavings(memberId),advance:await savingsAdvance(memberId),currentDue:await currentDue(memberId),dues,transactions:tx}}requirePerm(s,'savings.view');const month=String(options.month||monthKey()).slice(0,7),dues=(await many(T.MONTHLY_DUES,{},5000)).filter((d:A)=>asStatus(d.status)!=='MERGED'&&(!month||String(d.due_month).slice(0,7)===month)),names=await memberNameMap();const recent=desc((await many(T.TRANSACTIONS,{},3000)).filter((t:A)=>t.category==='SAVINGS'),'created_at').slice(0,50);const recentOut=[];for(const t of recent){const ds=await docsForSavings(t.txn_id);recentOut.push({...legacy(t),HAS_ATTACHMENT:ds.length>0,SUPPORTING_DOCUMENT_ID:ds[0]?.DOCUMENT_ID||''})}return {month,societyStartMonth:await societyStart(),dues:dues.map((d:A)=>({...legacy(d),DUE_MONTH:String(d.due_month).slice(0,7),MEMBER_NAME:names[d.member_id]||d.member_id})),recent:recentOut}}
async function getSavingsCollectionContext(token:string,memberId:string,m:string){const s=await sessionFromToken(token);if(s.role==='MEMBER')memberId=s.memberId;else requireAny(s,'savings.view','savings.collect');m=String(m||monthKey()).slice(0,7);if(!await one(T.MEMBERS,'member_id',memberId))throw new Error('Member not found.');if(m<await societyStart())throw new Error('সমিতির সঞ্চয় হিসাব '+await societyStart()+' থেকে শুরু।');const unit:any=await rpc('nd_savings_unit_for_month',{p_member_id:memberId,p_month:m}),adv=await savingsAdvance(memberId),preview=await duePreview(memberId,m,adv),due=preview?.row||null;return {memberId,month:m,unit:unit?legacy(unit):null,due,advance:adv,defaultAmount:due?Math.max(0,num(due.BALANCE)):(unit?num(unit.units)*num(unit.unit_amount):0),societyStartMonth:await societyStart()}}
async function getSavingsMultiCollectionContext(token:string,memberId:string,startMonth:string,endMonth:string){const s=await sessionFromToken(token);if(s.role==='MEMBER')memberId=s.memberId;else requireAny(s,'savings.view','savings.collect');if(!await one(T.MEMBERS,'member_id',memberId))throw new Error('Member not found.');const st=await societyStart();startMonth=String(startMonth||st).slice(0,7);endMonth=String(endMonth||startMonth).slice(0,7);if(startMonth<st)startMonth=st;let adv=await savingsAdvance(memberId);const items=[];for(const m of monthRange(startMonth,endMonth,120)){const p:any=await duePreview(memberId,m,adv);if(!p)continue;adv=p.advanceRemaining;const d=p.row;items.push({month:m,units:num(d.UNITS),unitAmount:num(d.UNIT_AMOUNT),dueAmount:num(d.DUE_AMOUNT),paidAmount:num(d.PAID_AMOUNT),advanceApplied:num(d.ADVANCE_APPLIED),balance:Math.max(0,num(d.BALANCE)),status:d.STATUS,existing:p.existing})}return {memberId,startMonth,endMonth,societyStartMonth:st,items,totalBalance:round2(items.reduce((z,x)=>z+x.balance,0)),advanceRemaining:adv}}
async function collectSavings(token:string,p:A){const s=await sessionFromToken(token);requirePerm(s,'savings.collect');const clean={...p};delete clean.supportingFileDataUrl;const out:any=await rpc('nd_collect_savings',{p_user_id:s.userId,p_payload:clean});if(p.supportingFileDataUrl){const file=await storeDataUrl(p.supportingFileDataUrl,'documents',p.supportingFileName||'bank_slip');for(const id of out.txnIds||[out.txnId]){if(!id)continue;await insert(T.DOCUMENTS,{document_id:await nextId('DOCUMENT','DOC-',8),member_id:out.memberId||p.memberId,related_type:'SAVINGS_TRANSACTION',related_id:id,title:'Savings supporting document',file_id:file.path,file_name:p.supportingFileName||file.name,mime_type:file.mime,status:'ACTIVE',created_at:now(),created_by:s.userId})}}return out}
async function getSavingsTransaction(token:string,txnId:string){const s=await sessionFromToken(token),t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t||t.category!=='SAVINGS')throw new Error('Savings transaction not found.');if(s.role==='MEMBER'&&t.member_id!==s.memberId)throw new Error('PERMISSION_DENIED');if(s.role!=='MEMBER')requireAny(s,'savings.view','accounts.view');return {transaction:legacy(t),due:t.related_id?legacy(await one(T.MONTHLY_DUES,'due_id',t.related_id)):null,receipt:t.receipt_id?legacy(await one(T.RECEIPTS,'receipt_id',t.receipt_id)):null,supportingDocuments:await docsForSavings(txnId)}}
async function reverseTxn(s:LegacySession,txnId:string,reason:string){return rpc('nd_reverse_transaction',{p_user_id:s.userId,p_txn_id:txnId,p_reason:reason})}
async function editSavingsTransaction(token:string,txnId:string,p:A){const s=await sessionFromToken(token);requireAny(s,'savings.edit','accounts.edit');if(s.role!=='ADMIN'&&!hasPerm(s,'savings.collect'))throw new Error('Collection permission required.');const reason=String(p?.reason||'').trim();if(!reason)throw new Error('Correction reason is required.');const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t||t.category!=='SAVINGS'||t.status!=='POSTED'||!['MONTHLY_SAVINGS','EXTRA_SAVINGS'].includes(t.type))throw new Error('Only monthly or additional savings deposits can be edited here.');const oldDocs=await docsForSavings(txnId),due=t.related_id?await one(T.MONTHLY_DUES,'due_id',t.related_id):null;const amount=round2(p.amount);if(amount<0)throw new Error('Amount invalid.');const rev=await reverseTxn(s,txnId,reason);await update(T.TRANSACTIONS,'txn_id',txnId,{status:'CORRECTED',updated_at:now(),updated_by:s.userId,correction_reason:reason});if(t.receipt_id)await update(T.RECEIPTS,'receipt_id',t.receipt_id,{status:'CANCELLED'});await rpc('nd_reconcile_savings_dues',{p_member_id:t.member_id,p_user_id:s.userId});if(amount<=0){await audit(s.userId,'EDIT','TRANSACTION',txnId,t,{reversalTxnId:rev,replacement:null,newAmount:0},reason);return {ok:true,reversalTxnId:typeof rev==='object'?rev.txnId||rev:rev,replacement:null}}const replacement:any=await collectSavings(token,{memberId:t.member_id,amount,type:p.type||t.type,month:p.month||(due?String(due.due_month).slice(0,7):monthOnly(t.txn_date)),date:dateOnly(p.date||t.txn_date),accountId:p.accountId||t.payment_account_id,paymentMethod:p.paymentMethod||t.payment_method,reference:p.reference!==undefined?p.reference:t.reference,notePurpose:p.notePurpose!==undefined?p.notePurpose:(p.note!==undefined?p.note:t.note_purpose||''),parentTxnId:t.txn_id,correctionReason:reason,supportingFileDataUrl:p.supportingFileDataUrl||'',supportingFileName:p.supportingFileName||''});if(!p.supportingFileDataUrl&&oldDocs.length){for(const d of oldDocs)await insert(T.DOCUMENTS,{document_id:await nextId('DOCUMENT','DOC-',8),member_id:t.member_id,related_type:'SAVINGS_TRANSACTION',related_id:replacement.txnId,title:d.TITLE,file_id:d.FILE_ID,file_name:d.FILE_NAME,mime_type:d.MIME_TYPE,status:'ACTIVE',created_at:now(),created_by:s.userId})}await audit(s.userId,'EDIT','TRANSACTION',txnId,t,{reversalTxnId:rev,replacement,newData:p},reason);return {ok:true,reversalTxnId:typeof rev==='object'?rev.txnId||rev:rev,replacement}}
async function correctSavingsTransaction(token:string,txnId:string,newAmount:A,reason:string){const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t)throw new Error('Savings transaction not found.');const d=t.related_id?await one(T.MONTHLY_DUES,'due_id',t.related_id):null;return editSavingsTransaction(token,txnId,{amount:newAmount,type:t.type,month:d?String(d.due_month).slice(0,7):monthOnly(t.txn_date),date:dateOnly(t.txn_date),accountId:t.payment_account_id,paymentMethod:t.payment_method,reference:t.reference,notePurpose:t.note_purpose||'',reason})}
async function getReceipt(token:string,receiptId:string){const s=await sessionFromToken(token),r=await one(T.RECEIPTS,'receipt_id',receiptId);if(!r)throw new Error('Receipt not found.');if(s.role==='MEMBER'&&r.member_id!==s.memberId)throw new Error('PERMISSION_DENIED');if(s.role!=='MEMBER')requirePerm(s,'receipts.view');const [m,t,cm]=await Promise.all([one(T.MEMBERS,'member_id',r.member_id),one(T.TRANSACTIONS,'txn_id',r.txn_id),configMap()]);return {receipt:legacy(r),member:legacy(m),transaction:legacy(t),supportingDocuments:t?await docsForSavings(t.txn_id):[],config:{nameBn:cm.SOCIETY_NAME_BN||'',nameEn:cm.SOCIETY_NAME_EN||'',estd:cm.ESTD_YEAR||'2026',tagline:cm.TAGLINE_BN||'',address:cm.SOCIETY_ADDRESS||'',mobile:cm.SOCIETY_MOBILE||'',email:cm.SOCIETY_EMAIL||'',currency:cm.CURRENCY_SYMBOL||'৳'}}}
async function recordReceiptPrint(token:string,receiptId:string){const s=await sessionFromToken(token),r=await one(T.RECEIPTS,'receipt_id',receiptId);if(!r)throw new Error('Receipt not found.');if(s.role==='MEMBER'&&r.member_id!==s.memberId)throw new Error('PERMISSION_DENIED');if(s.role!=='MEMBER')requirePerm(s,'receipts.print');await update(T.RECEIPTS,'receipt_id',receiptId,{print_count:num(r.print_count)+1,last_printed_at:now()});return {ok:true}}
async function listReceipts(token:string,options:A={}){const s=await sessionFromToken(token);if(s.role!=='MEMBER')requirePerm(s,'receipts.view');let q:any=sb().from(T.RECEIPTS).select('*').order('created_at',{ascending:false}).limit(Math.min(500,num(options.limit||200)));if(s.role==='MEMBER')q=q.eq('member_id',s.memberId);else if(options.memberId)q=q.eq('member_id',options.memberId);if(options.q){const x=String(options.q);q=q.or(`receipt_id.ilike.%${x}%,member_id.ilike.%${x}%,reference.ilike.%${x}%`)}const {data,error}=await q;if(error)throw error;return upperRows(data||[])}
async function getMemberLedger(token:string,memberId:string,options:A={}){const s=await sessionFromToken(token);if(s.role==='MEMBER')memberId=s.memberId;else requireAny(s,'accounts.view','members.view');let rows=await many(T.TRANSACTIONS,{member_id:memberId},5000);rows=rows.filter((r:A)=>['POSTED','REVERSED','CORRECTED'].includes(r.status));if(options.category)rows=rows.filter((r:A)=>r.category===options.category);if(options.from)rows=rows.filter((r:A)=>String(r.txn_date)>=options.from);if(options.to)rows=rows.filter((r:A)=>String(r.txn_date)<=options.to);rows.sort((a:A,b:A)=>(String(a.txn_date)+String(a.created_at)).localeCompare(String(b.txn_date)+String(b.created_at)));let balance=0;const out=rows.map((r:A)=>{balance=round2(balance+(r.direction==='CREDIT'?num(r.amount):-num(r.amount)));return {...legacy(r),RUNNING_BALANCE:balance}}).reverse();return {memberId,rows:out,closingBalance:balance,savingsBalance:await memberSavings(memberId),outstandingDue:await currentDue(memberId),loanOutstanding:await loanOutstanding(memberId)}}
async function addBankAccount(token:string,p:A={}){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');if(!p.name)throw new Error('Account name required.');const code=p.accountCode||('109'+await nextId('BANK_CODE','',3));if(await one(T.CHART_OF_ACCOUNTS,'account_code',code))throw new Error('Account code already exists.');await insert(T.CHART_OF_ACCOUNTS,{account_code:code,account_name:p.name,account_type:'ASSET',parent_code:'',status:'ACTIVE',system_account:''});const id=await nextId('ACCOUNT','ACC-',5);await insert(T.BANK_ACCOUNTS,{account_id:id,account_code:code,account_name:p.name,type:p.type||'BANK',bank_name:p.bankName||'',account_no:p.accountNo||'',branch:p.branch||'',opening_balance:round2(p.openingBalance),status:'ACTIVE',created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId});await audit(s.userId,'CREATE','BANK_ACCOUNT',id,{},p,'Bank/cash account created');return {ok:true,accountId:id}}
async function approvedProfitAmount(profitId:string){return round2(await rpc('nd_profit_approved_amount',{p_profit_id:profitId}))}
async function reservedProfitAmount(profitId:string){return round2(await rpc('nd_profit_reserved_amount',{p_profit_id:profitId}))}
async function linkedProfitForIncome(income:A){if(income?.profit_id)return one(T.PROFIT_RECORDS,'profit_id',income.profit_id);if(income?.income_id){const {data,error}=await sb().from(T.PROFIT_RECORDS).select('*').eq('source_income_id',income.income_id).maybeSingle();if(error)throw error;return data}return null}
async function getFinancePage(token:string){const s=await sessionFromToken(token);requirePerm(s,'accounts.view');const [income,expenses,gl]=await Promise.all([many(T.INCOME,{},100,'date'),many(T.EXPENSES,{},100,'date'),many(T.GENERAL_LEDGER,{},200,'created_at')]);const io=[];for(const r of income){const p=await linkedProfitForIncome(r),dist=p?await approvedProfitAmount(p.profit_id):0;let v=r.voucher_id?await one(T.VOUCHERS,'voucher_id',r.voucher_id):null;if(!v&&r.txn_id){const vs=await many(T.VOUCHERS,{txn_id:r.txn_id},10);v=vs.find((x:A)=>x.status==='POSTED')||vs[0]}io.push({...legacy(r),INCOME_TYPE:r.income_type||'GENERAL',VOUCHER_ID:r.voucher_id||v?.voucher_id||'',PROFIT_STATUS:p?.status||'',DISTRIBUTED_AMOUNT:dist,UNDISTRIBUTED_AMOUNT:p?round2(Math.max(0,num(p.amount)-dist)):0})}const eo=[];for(const r of expenses){let v=r.voucher_id?await one(T.VOUCHERS,'voucher_id',r.voucher_id):null;if(!v&&r.txn_id){const vs=await many(T.VOUCHERS,{txn_id:r.txn_id},10);v=vs.find((x:A)=>x.status==='POSTED')||vs[0]}eo.push({...legacy(r),VOUCHER_ID:r.voucher_id||v?.voucher_id||'',ALLOCATION_METHOD:r.allocation_method||'NORMAL'})}return {accounts:await accountBalances(),income:io,expenses:eo,ledger:upperRows(gl),profitLoss:await getProfitLossFor(s)}}
async function getIncomeFormOptions(token:string){const s=await sessionFromToken(token);requireAny(s,'accounts.edit','accounts.view');return {sources:upperRows(await many(T.PROFIT_SOURCES,{status:'ACTIVE'},500,'created_at')),investments:upperRows((await many(T.INVESTMENTS,{},500,'created_at')).filter((x:A)=>x.status!=='CANCELLED'))}}
async function getIncomeDetails(token:string,incomeId:string){const s=await sessionFromToken(token);requireAny(s,'accounts.view','audit.view');const income=await one(T.INCOME,'income_id',incomeId);if(!income)throw new Error('Income not found.');const profit=await linkedProfitForIncome(income);let voucher=income.voucher_id?await one(T.VOUCHERS,'voucher_id',income.voucher_id):null;if(!voucher&&income.txn_id){const vs=await many(T.VOUCHERS,{txn_id:income.txn_id},10);voucher=vs.find((x:A)=>x.status==='POSTED')||vs[0]}const distributed=profit?await approvedProfitAmount(profit.profit_id):0,reserved=profit?await reservedProfitAmount(profit.profit_id):0;return {income:{...legacy(income),INCOME_TYPE:income.income_type||'GENERAL',VOUCHER_ID:income.voucher_id||voucher?.voucher_id||'',PROFIT_ID:income.profit_id||profit?.profit_id||'',DISTRIBUTED_AMOUNT:distributed,UNDISTRIBUTED_AMOUNT:profit?round2(Math.max(0,num(profit.amount)-reserved)):0,RESERVED_AMOUNT:reserved},transaction:legacy(await one(T.TRANSACTIONS,'txn_id',income.txn_id)),voucher:legacy(voucher),profit:profit?{...legacy(profit),DISTRIBUTED_AMOUNT:distributed,UNDISTRIBUTED_AMOUNT:round2(Math.max(0,num(profit.amount)-reserved)),RESERVED_AMOUNT:reserved}:null,distributions:profit?upperRows(await many(T.PROFIT_DISTRIBUTIONS,{profit_id:profit.profit_id},500)):[],journal:upperRows(await many(T.GENERAL_LEDGER,{txn_id:income.txn_id},100)),audit:upperRows(await many(T.AUDIT_LOG,{entity_id:incomeId},100))}}
async function createIncome(token:string,p:A={}){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');return rpc('nd_create_income',{p_user_id:s.userId,p_payload:p})}
async function previewExpenseAllocation(token:string,p:A={}){const s=await sessionFromToken(token);requireAny(s,'accounts.edit','accounts.view');if(expenseAllocationMethod(p.allocationMethod)!=='UNIT_BASED')throw new Error('Unit-based allocation must be selected for preview.');return rpc('nd_preview_unit_expense',{p_amount:round2(p.amount),p_date:dateOnly(p.date||today())})}
async function createExpense(token:string,p:A={}){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');const method=expenseAllocationMethod(p.allocationMethod);const clean={...p,allocationMethod:method};delete clean.documentDataUrl;let uploaded:A=null;try{if(p.documentDataUrl){uploaded=await storeDataUrl(p.documentDataUrl,'documents','expense_'+Date.now());clean.documentFileId=uploaded.path}const fn=method==='UNIT_BASED'?'nd_create_unit_expense':'nd_create_expense';return await rpc(fn,{p_user_id:s.userId,p_payload:clean})}catch(e){if(uploaded?.path){try{await sb().storage.from('documents').remove([uploaded.path])}catch{}}throw e}}
async function listVouchers(token:string,options:A={}){const s=await sessionFromToken(token);if(s.role!=='MEMBER')requireAny(s,'receipts.view','accounts.view');let q:any=sb().from(T.VOUCHERS).select('*').order('created_at',{ascending:false}).limit(Math.min(1000,num(options.limit||300)));if(s.role==='MEMBER')q=q.eq('member_id',s.memberId);if(options.q){const x=String(options.q);q=q.or(`voucher_id.ilike.%${x}%,txn_id.ilike.%${x}%,member_id.ilike.%${x}%,payee.ilike.%${x}%,purpose.ilike.%${x}%,reference.ilike.%${x}%`)}const {data,error}=await q;if(error)throw error;return upperRows(data||[])}
async function getVoucher(token:string,voucherId:string){const s=await sessionFromToken(token),v=await one(T.VOUCHERS,'voucher_id',voucherId);if(!v)throw new Error('Voucher not found.');if(s.role==='MEMBER'&&v.member_id!==s.memberId)throw new Error('PERMISSION_DENIED');if(s.role!=='MEMBER')requireAny(s,'receipts.view','accounts.view');const [member,account,expenses,incomes,cm]=await Promise.all([v.member_id?one(T.MEMBERS,'member_id',v.member_id):null,one(T.BANK_ACCOUNTS,'account_id',v.account_id),many(T.EXPENSES,{},1000),many(T.INCOME,{},1000),configMap()]);const expense=expenses.find((x:A)=>x.voucher_id===v.voucher_id||x.txn_id===v.txn_id)||null,income=incomes.find((x:A)=>x.voucher_id===v.voucher_id||x.txn_id===v.txn_id)||null,profit=income?await linkedProfitForIncome(income):null,source=profit?await one(T.PROFIT_SOURCES,'source_id',profit.source_id):null,alloc=expense&&expense.allocation_method==='UNIT_BASED'?await many(T.EXPENSE_ALLOCATIONS,{expense_id:expense.expense_id},1000):[];return {voucher:legacy(v),member:legacy(member),account:legacy(account),expense:legacy(expense),income:legacy(income),profit:legacy(profit),profitSource:legacy(source),allocations:upperRows(alloc),allocationSummary:expense&&expense.allocation_method==='UNIT_BASED'?{method:expense.allocation_method,totalUnits:num(expense.total_units),memberCount:num(expense.member_count),allocatedAmount:num(expense.allocated_amount),status:expense.allocation_status}:null,config:{nameBn:cm.SOCIETY_NAME_BN||'',nameEn:cm.SOCIETY_NAME_EN||'',estd:cm.ESTD_YEAR||'2026',tagline:cm.TAGLINE_BN||'',address:cm.SOCIETY_ADDRESS||'',mobile:cm.SOCIETY_MOBILE||'',email:cm.SOCIETY_EMAIL||''}}}
async function getExpenseDetails(token:string,expenseId:string){const s=await sessionFromToken(token);requireAny(s,'accounts.view','audit.view');const e=await one(T.EXPENSES,'expense_id',expenseId);if(!e)throw new Error('Expense not found.');const t=await one(T.TRANSACTIONS,'txn_id',e.txn_id),v=e.voucher_id?await one(T.VOUCHERS,'voucher_id',e.voucher_id):null,a=e.allocation_method==='UNIT_BASED'?await many(T.EXPENSE_ALLOCATIONS,{expense_id:expenseId},2000):[];return {expense:legacy(e),transaction:legacy(t),voucher:legacy(v),allocations:upperRows(a),journal:t?upperRows(await many(T.GENERAL_LEDGER,{txn_id:t.txn_id},100)):[],audit:upperRows(await many(T.AUDIT_LOG,{entity_id:expenseId},100))}}
async function reverseIncome(token:string,incomeId:string,reason:string){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');reason=String(reason||'').trim();if(!reason)throw new Error('Reversal reason required.');const i=await one(T.INCOME,'income_id',incomeId);if(!i||['CANCELLED','REVERSED'].includes(asStatus(i.status)))throw new Error('Income is not eligible for reversal.');const p=await linkedProfitForIncome(i);if(p&&await reservedProfitAmount(p.profit_id)>0)throw new Error('Cancel/reverse all related profit distributions before reversing this income.');const t=await one(T.TRANSACTIONS,'txn_id',i.txn_id);if(!t||t.status!=='POSTED')throw new Error('Income transaction is not eligible for reversal.');const rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',updated_at:now(),updated_by:s.userId,correction_reason:reason});await update(T.INCOME,'income_id',incomeId,{status:'REVERSED',updated_at:now(),updated_by:s.userId});if(i.voucher_id)await update(T.VOUCHERS,'voucher_id',i.voucher_id,{status:'CANCELLED'});if(p)await update(T.PROFIT_RECORDS,'profit_id',p.profit_id,{status:'REVERSED',distributed_amount:0,undistributed_amount:0,updated_at:now(),updated_by:s.userId});await audit(s.userId,'REVERSE','INCOME',incomeId,i,{reversalTxnId:rev,profitId:p?.profit_id||''},reason);return {ok:true,incomeId,reversalTxnId:rev,profitId:p?.profit_id||''}}
async function updateIncome(token:string,incomeId:string,p:A={},reason=''){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');reason=String(reason||p.reason||'').trim();if(!reason)throw new Error('Modification reason required.');const old=await one(T.INCOME,'income_id',incomeId);if(!old||['CANCELLED','REVERSED'].includes(asStatus(old.status)))throw new Error('Income is not editable.');const oldProfit=await linkedProfitForIncome(old);if(oldProfit&&await reservedProfitAmount(oldProfit.profit_id)>0)throw new Error('Cancel/reverse all related profit distributions before editing this income.');const oldTxn=await one(T.TRANSACTIONS,'txn_id',old.txn_id);const rev=await reverseTxn(s,oldTxn.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',oldTxn.txn_id,{status:'CORRECTED',correction_reason:reason,updated_at:now(),updated_by:s.userId});if(old.voucher_id)await update(T.VOUCHERS,'voucher_id',old.voucher_id,{status:'CANCELLED'});if(oldProfit)await update(T.PROFIT_RECORDS,'profit_id',oldProfit.profit_id,{status:'REVERSED',updated_at:now(),updated_by:s.userId});await update(T.INCOME,'income_id',incomeId,{status:'CORRECTED',updated_at:now(),updated_by:s.userId});const out:any=await createIncome(token,{...p,amount:p.amount===undefined?old.amount:p.amount,date:p.date||old.date,category:p.category===undefined?old.category:p.category,accountId:p.accountId||old.account_id,reference:p.reference===undefined?old.reference:p.reference,description:p.description===undefined?old.description:p.description,incomeType:p.incomeType||old.income_type,note:p.note===undefined?old.note:p.note,clientRequestId:''});await audit(s.userId,'UPDATE','INCOME',incomeId,old,{reversalTxnId:rev,replacement:out},reason);return {ok:true,incomeId,reversalTxnId:rev,replacementTxnId:out.txnId,voucherId:out.voucherId,profitId:out.profitId||'',incomeType:out.incomeType||'GENERAL'}}
async function reverseUnitExpense(s:LegacySession,e:A,reason:string){const alloc=await many(T.EXPENSE_ALLOCATIONS,{expense_id:e.expense_id},5000);for(const a of alloc){if(a.txn_id&&a.status==='POSTED'){await reverseTxn(s,a.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',a.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.EXPENSE_ALLOCATIONS,'allocation_id',a.allocation_id,{status:'REVERSED',updated_at:now(),updated_by:s.userId})}}const mt=await one(T.TRANSACTIONS,'txn_id',e.txn_id);const rev=mt?await reverseTxn(s,mt.txn_id,reason):'';if(mt)await update(T.TRANSACTIONS,'txn_id',mt.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.EXPENSES,'expense_id',e.expense_id,{status:'REVERSED',allocation_status:'REVERSED',updated_at:now(),updated_by:s.userId});if(e.voucher_id)await update(T.VOUCHERS,'voucher_id',e.voucher_id,{status:'CANCELLED'});await audit(s.userId,'REVERSE','EXPENSE',e.expense_id,e,{reversalTxnId:rev},reason);return {ok:true,expenseId:e.expense_id,reversalTxnId:rev}}
async function reverseExpense(token:string,expenseId:string,reason:string){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');reason=String(reason||'').trim();if(!reason)throw new Error('Reversal reason required.');const e=await one(T.EXPENSES,'expense_id',expenseId);if(!e)throw new Error('Expense not found.');if((e.allocation_method||'NORMAL')==='UNIT_BASED')return reverseUnitExpense(s,e,reason);const t=await one(T.TRANSACTIONS,'txn_id',e.txn_id);if(!t||t.status!=='POSTED')throw new Error('Expense is not eligible for reversal.');const rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.EXPENSES,'expense_id',expenseId,{status:'REVERSED',updated_at:now(),updated_by:s.userId});if(e.voucher_id)await update(T.VOUCHERS,'voucher_id',e.voucher_id,{status:'CANCELLED'});await audit(s.userId,'REVERSE','EXPENSE',expenseId,e,{reversalTxnId:rev},reason);return {ok:true,expenseId,reversalTxnId:rev}}
async function updateNormalExpense(token:string,expenseId:string,p:A={},reason=''){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');reason=String(reason||p.reason||'').trim();if(!reason)throw new Error('Modification reason required.');const e=await one(T.EXPENSES,'expense_id',expenseId);if(!e||e.status!=='POSTED')throw new Error('Expense is not editable.');if((e.allocation_method||'NORMAL')==='UNIT_BASED')throw new Error('Unit-based expense must be reversed as one complete allocation and recreated.');const t=await one(T.TRANSACTIONS,'txn_id',e.txn_id),rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'CORRECTED',correction_reason:reason,updated_at:now(),updated_by:s.userId});if(e.voucher_id)await update(T.VOUCHERS,'voucher_id',e.voucher_id,{status:'CANCELLED'});await update(T.EXPENSES,'expense_id',expenseId,{status:'CORRECTED',updated_at:now(),updated_by:s.userId});const out:any=await createExpense(token,{...p,allocationMethod:'NORMAL',amount:p.amount===undefined?e.amount:p.amount,date:p.date||e.date,category:p.category===undefined?e.category:p.category,accountId:p.accountId||e.account_id,reference:p.reference===undefined?e.reference:p.reference,description:p.description===undefined?e.description:p.description,clientRequestId:''});await audit(s.userId,'UPDATE','EXPENSE',expenseId,e,{reversalTxnId:rev,replacement:out},reason);return {ok:true,expenseId,reversalTxnId:rev,replacementTxnId:out.txnId,voucherId:out.voucherId}}
