async function correctSimpleTransaction(token:string,txnId:string,newAmount:A,reason:string){
  const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');
  if(!reason)throw new Error('Correction reason required.');
  const t=await one(T.TRANSACTIONS,'txn_id',txnId);
  if(!t||t.status!=='POSTED')throw new Error('Transaction not eligible.');
  if(t.type==='ASSOCIATION_EXPENSE_DEDUCTION')throw new Error('Reverse the linked unit-based expense and recreate it.');
  if(t.type==='EXPENSE'){
    const linkedExpense=await one(T.EXPENSES,'expense_id',t.related_id);
    if(linkedExpense&&linkedExpense.allocation_method==='UNIT_BASED')throw new Error('Unit-based expense must be reversed as one complete allocation and recreated.');
  }
  if(['SAVINGS','LOAN'].includes(t.category))throw new Error('Use the dedicated savings/loan correction workflow.');
  const originalGl=await many(T.GENERAL_LEDGER,{txn_id:t.txn_id},500,'created_at',true);
  const rev=await reverseTxn(s,t.txn_id,reason);
  await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'CORRECTED',correction_reason:reason,updated_at:now(),updated_by:s.userId});
  let replacement:string|null=null;const amount=round2(newAmount);
  if(amount>0){
    const ratio=num(t.amount)>0?amount/num(t.amount):0,newId=await nextId('TXN','TRX-',8),n={...t};
    n.txn_id=newId;n.amount=amount;n.principal_amount=round2(num(t.principal_amount)*ratio);n.profit_amount=round2(num(t.profit_amount)*ratio);n.penalty_amount=round2(num(t.penalty_amount)*ratio);n.status='POSTED';n.parent_txn_id=t.txn_id;n.correction_reason=reason;n.created_at=now();n.created_by=s.userId;n.updated_at=now();n.updated_by=s.userId;
    await insert(T.TRANSACTIONS,n);
    const lines=originalGl.map((g:A)=>({accountCode:String(g.account_code),debit:round2(num(g.debit)*ratio),credit:round2(num(g.credit)*ratio)}));
    if(lines.length)await rpc('nd_post_journal',{p_user_id:s.userId,p_txn_id:newId,p_entry_date:t.txn_date,p_lines:lines,p_member_id:t.member_id||'',p_related_id:t.related_id||'',p_description:'Corrected: '+(t.description||'')});
    replacement=newId;
  }
  if(t.category==='INCOME'){
    const inc=await one(T.INCOME,'income_id',t.related_id);if(inc)await update(T.INCOME,'income_id',inc.income_id,{amount,txn_id:replacement||'',status:amount>0?'POSTED':'CANCELLED'});
  }
  if(t.category==='EXPENSE'){
    const exp=await one(T.EXPENSES,'expense_id',t.related_id);if(exp)await update(T.EXPENSES,'expense_id',exp.expense_id,{amount,txn_id:replacement||'',status:amount>0?'POSTED':'CANCELLED',updated_at:now(),updated_by:s.userId});
  }
  const vouchers=await many(T.VOUCHERS,{txn_id:txnId,status:'POSTED'},50,'created_at');const oldVoucher=vouchers[0];
  if(oldVoucher){await update(T.VOUCHERS,'voucher_id',oldVoucher.voucher_id,{status:'CANCELLED'});if(replacement){const nv={...oldVoucher,voucher_id:await nextVoucher(),txn_id:replacement,amount,status:'POSTED',created_at:now(),created_by:s.userId};await insert(T.VOUCHERS,nv)}}
  await audit(s.userId,'CORRECT','TRANSACTION',txnId,t,{reversal:rev,replacement,newAmount:amount},reason);
  return {ok:true,reversalTxnId:rev,replacementTxnId:replacement};
}
async function listFinancialTransactions(token:string,options:A={}){const s=await sessionFromToken(token);requireAny(s,'audit.view','accounts.view');let rows=await many(T.TRANSACTIONS,{},10000,'created_at');if(options.status)rows=rows.filter((r:A)=>r.status===options.status);if(options.category)rows=rows.filter((r:A)=>r.category===options.category);if(options.type)rows=rows.filter((r:A)=>r.type===options.type);if(options.memberId)rows=rows.filter((r:A)=>r.member_id===options.memberId);if(options.from)rows=rows.filter((r:A)=>String(r.txn_date)>=options.from);if(options.to)rows=rows.filter((r:A)=>String(r.txn_date)<=options.to);if(options.q){const q=String(options.q).toLowerCase();rows=rows.filter((r:A)=>[r.txn_id,r.member_id,r.type,r.category,r.description,r.reference,r.related_id,r.note_purpose].join(' ').toLowerCase().includes(q))}const exps=await many(T.EXPENSES,{},5000),emap=Object.fromEntries(exps.map((e:A)=>[e.expense_id,e]));return rows.slice(0,Math.min(1000,num(options.limit||300))).map((r:A)=>{const dedicated=['MONTHLY_SAVINGS','EXTRA_SAVINGS','LOAN_PAYMENT','PROFIT_ENTRY'].includes(r.type)||String(r.type).startsWith('INVESTMENT_RETURN_'),unitExpense=r.type==='EXPENSE'&&emap[r.related_id]?.allocation_method==='UNIT_BASED',protectedType=['INVESTMENT_CLOSURE','PROFIT_DISTRIBUTION','LOAN_DISBURSEMENT','INVESTMENT_PURCHASE','ASSOCIATION_EXPENSE_DEDUCTION'].includes(r.type)||unitExpense,editable=r.status==='POSTED'&&(dedicated||(!protectedType&&!['SAVINGS','LOAN'].includes(r.category)));return {...legacy(r),CAN_REVERSE:r.status==='POSTED'&&!String(r.type).startsWith('REVERSAL_'),CAN_EDIT:editable}})}
async function getFinancialTransaction(token:string,txnId:string){const s=await sessionFromToken(token);requireAny(s,'audit.view','accounts.view');const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t)throw new Error('Transaction not found.');const e=t.related_id?await one(T.EXPENSES,'expense_id',t.related_id):null;return {transaction:legacy(t),journal:upperRows(await many(T.GENERAL_LEDGER,{txn_id:txnId},200)),audit:upperRows(await many(T.AUDIT_LOG,{entity_id:txnId},200)),reversals:upperRows(await many(T.TRANSACTIONS,{parent_txn_id:txnId},200)),expense:legacy(e),expenseAllocations:e?.allocation_method==='UNIT_BASED'?upperRows(await many(T.EXPENSE_ALLOCATIONS,{expense_id:e.expense_id},5000)):[]}}
async function reverseFinancialTransaction(token:string,txnId:string,reason:string){const s=await sessionFromToken(token);requireAny(s,'accounts.edit');if(!reason)throw new Error('Reversal reason required.');const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t||t.status!=='POSTED'||String(t.type).startsWith('REVERSAL_'))throw new Error('Transaction is not eligible for reversal.');if(['MONTHLY_SAVINGS','EXTRA_SAVINGS'].includes(t.type))return correctSavingsTransaction(token,txnId,0,reason);if(t.type==='LOAN_PAYMENT')return correctLoanPayment(token,txnId,0,reason);if(t.type==='LOAN_DISBURSEMENT')return reverseLoanDisbursement(token,t.related_id,reason);if(t.type==='INVESTMENT_PURCHASE')return cancelInvestment(token,t.related_id,reason);if(String(t.type).startsWith('INVESTMENT_RETURN_')){const rs=await many(T.INVESTMENT_RETURNS,{txn_id:txnId},5);if(!rs[0])throw new Error('Investment return link missing.');return reverseInvestmentReturn(token,rs[0].return_id,reason)}if(t.type==='INVESTMENT_CLOSURE')return reverseInvestmentClosure(token,t.related_id,reason);if(t.type==='PROFIT_DISTRIBUTION')return reverseProfitDistribution(token,t.related_id,reason);if(t.type==='INCOME')return reverseIncome(token,t.related_id,reason);if(t.type==='EXPENSE')return reverseExpense(token,t.related_id,reason);if(t.type==='PROFIT_ENTRY'){const ps=await many(T.PROFIT_RECORDS,{source_txn_id:txnId},5);if(!ps[0])throw new Error('Profit record link missing.');return reverseProfitRecord(token,ps[0].profit_id,reason)}const rev=await reverseTxn(s,txnId,reason);await update(T.TRANSACTIONS,'txn_id',txnId,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});return {ok:true,reversalTxnId:rev}}
async function correctFinancialTransaction(token:string,txnId:string,p:A={}){if(!p.reason)throw new Error('Correction reason required.');const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t||t.status!=='POSTED')throw new Error('Transaction is not editable.');if(['MONTHLY_SAVINGS','EXTRA_SAVINGS'].includes(t.type))return correctSavingsTransaction(token,txnId,p.amount,p.reason);if(t.type==='LOAN_PAYMENT')return correctLoanPayment(token,txnId,p.amount,p.reason);if(String(t.type).startsWith('INVESTMENT_RETURN_')){const r=(await many(T.INVESTMENT_RETURNS,{txn_id:txnId},5))[0];if(!r)throw new Error('Investment return link missing.');return editInvestmentReturn(token,r.return_id,p,p.reason)}if(t.type==='PROFIT_ENTRY'){const r=(await many(T.PROFIT_RECORDS,{source_txn_id:txnId},5))[0];if(!r)throw new Error('Profit record link missing.');return updateProfitRecord(token,r.profit_id,p,p.reason)}if(t.type==='INCOME')return updateIncome(token,t.related_id,p,p.reason);if(t.type==='EXPENSE'){const e=await one(T.EXPENSES,'expense_id',t.related_id);if(e?.allocation_method==='UNIT_BASED')throw new Error('Unit-based expense must be reversed as one complete allocation and recreated.');return updateNormalExpense(token,t.related_id,p,p.reason)}if(['INVESTMENT_CLOSURE','PROFIT_DISTRIBUTION','LOAN_DISBURSEMENT','INVESTMENT_PURCHASE','ASSOCIATION_EXPENSE_DEDUCTION'].includes(t.type))throw new Error('Reverse this transaction and recreate it with correct values.');return correctSimpleTransaction(token,txnId,p.amount,p.reason)}
