async function correctLoanPayment(token:string,txnId:string,newAmount:A,reason:string){const s=await sessionFromToken(token);requirePerm(s,'accounts.edit');if(!reason)throw new Error('Correction reason required.');const t=await one(T.TRANSACTIONS,'txn_id',txnId);if(!t||t.type!=='LOAN_PAYMENT'||t.status!=='POSTED')throw new Error('Loan payment not found.');const pay=await one(T.LOAN_PAYMENTS,'txn_id',txnId);if(!pay)throw new Error('Loan payment record missing.');const allocs=await many(T.LOAN_PAYMENT_ALLOCATIONS,{payment_id:pay.payment_id},1000);for(const a of allocs){const sch=await one(T.LOAN_SCHEDULE,'schedule_id',a.schedule_id);if(sch)await update(T.LOAN_SCHEDULE,'schedule_id',a.schedule_id,{principal_paid:Math.max(0,num(sch.principal_paid)-num(a.principal_amount)),profit_paid:Math.max(0,num(sch.profit_paid)-num(a.profit_amount)),penalty_paid:Math.max(0,num(sch.penalty_paid)-num(a.penalty_amount)),status:'DUE',paid_at:null})}const rev=await reverseTxn(s,txnId,reason);await update(T.TRANSACTIONS,'txn_id',txnId,{status:'CORRECTED',correction_reason:reason,updated_at:now(),updated_by:s.userId});if(t.receipt_id)await update(T.RECEIPTS,'receipt_id',t.receipt_id,{status:'CANCELLED'});await rpc('nd_refresh_loan_status',{p_loan_id:t.related_id,p_user_id:s.userId});let replacement:A=null;if(round2(newAmount)>0)replacement=await collectLoanPayment(token,{loanId:t.related_id,amount:round2(newAmount),date:dateOnly(t.txn_date),accountId:t.payment_account_id,paymentMethod:t.payment_method,reference:t.reference});await audit(s.userId,'CORRECT','LOAN_PAYMENT',txnId,t,{reversal:rev,replacement},reason);return {ok:true,reversalTxnId:rev,replacement}}
async function reverseLoanDisbursement(token:string,loanId:string,reason:string){const s=await sessionFromToken(token);requireAny(s,'loans.approve','accounts.edit');if(!reason)throw new Error('Reversal reason required.');const l=await one(T.LOANS,'loan_id',loanId);if(!l||!l.disbursement_txn_id)throw new Error('Disbursed loan not found.');const pays=await many(T.LOAN_PAYMENTS,{loan_id:loanId},1000);for(const p of pays){const t=await one(T.TRANSACTIONS,'txn_id',p.txn_id);if(t&&effective(t.status))throw new Error('Loan disbursement cannot be reversed after a posted installment. Reverse installments first.')}const t=await one(T.TRANSACTIONS,'txn_id',l.disbursement_txn_id);if(!t||t.status!=='POSTED')throw new Error('Disbursement transaction is not eligible.');const rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});const sch=await many(T.LOAN_SCHEDULE,{loan_id:loanId},1000);for(const x of sch)await update(T.LOAN_SCHEDULE,'schedule_id',x.schedule_id,{status:'VOID',paid_at:null});await update(T.LOANS,'loan_id',loanId,{status:'APPROVED',disbursed_at:null,disbursement_txn_id:'',outstanding_principal:0,next_due_date:null,updated_at:now(),updated_by:s.userId});await audit(s.userId,'REVERSE','LOAN_DISBURSEMENT',loanId,l,{reversalTxnId:rev},reason);return {ok:true,reversalTxnId:rev}}
