async function updateInvestment(token:string,investmentId:string,p:A={},reason=''){const s=await sessionFromToken(token);requireAny(s,'investments.edit');if(!reason)throw new Error('Modification reason required.');const inv=await one(T.INVESTMENTS,'investment_id',investmentId);if(!inv)throw new Error('Investment not found.');if(!['ACTIVE','PARTIALLY_RETURNED','PRINCIPAL_RETURNED'].includes(asStatus(inv.status)))throw new Error('Closed/cancelled investment cannot be edited. Reverse the closure first.');const up:A={updated_at:now(),updated_by:s.userId},map:A={type:'type',name:'name',startDate:'start_date',location:'location',landSize:'land_size',mouza:'mouza',dag:'dag',khatian:'khatian',partner:'partner',responsiblePerson:'responsible_person',notes:'notes'};for(const [k,v] of Object.entries(map))if(p[k]!==undefined)up[v as string]=p[k];if(p.expectedReturnRate!==undefined)up.expected_return_rate=num(p.expectedReturnRate);if(p.expectedEndDate!==undefined)up.expected_end_date=dateOnly(p.expectedEndDate)||null;if(p.ownershipPercent!==undefined)up.ownership_percent=num(p.ownershipPercent);const oldCost=num(inv.total_invested||inv.amount),newPrincipal=p.amount===undefined?num(inv.amount):round2(p.amount),newTotal=p.totalInvested===undefined?oldCost:round2(p.totalInvested);if(newPrincipal<=0||newTotal+.01<newPrincipal)throw new Error('Invalid investment principal/total cost.');let reversalTxnId='',purchaseTxnId=inv.purchase_txn_id;if(Math.abs(newTotal-oldCost)>.009||Math.abs(newPrincipal-num(inv.amount))>.009){if((await investmentReturns(investmentId)).length||await investmentActiveClosure(investmentId))throw new Error('Amount cannot be edited after a return or closure. Reverse dependent transactions first.');const oldTxn=await one(T.TRANSACTIONS,'txn_id',inv.purchase_txn_id);if(!oldTxn||oldTxn.status!=='POSTED')throw new Error('Original purchase transaction is not editable.');const account=await accountById(p.accountId||oldTxn.payment_account_id),bal=num(await rpc('nd_account_balance',{p_account_id:account.account_id})),additional=account.account_id===oldTxn.payment_account_id?Math.max(0,newTotal-num(oldTxn.amount)):newTotal;if(additional>bal+.01)throw new Error('Corrected investment purchase exceeds available balance: '+bal);reversalTxnId=await reverseTxn(s,oldTxn.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',oldTxn.txn_id,{status:'CORRECTED',correction_reason:reason,updated_at:now(),updated_by:s.userId});const nt=await createInvestmentPurchaseTxn(s,investmentId,p.name||inv.name,newTotal,dateOnly(p.startDate||oldTxn.txn_date),account,{paymentMethod:p.paymentMethod||oldTxn.payment_method,reference:p.reference===undefined?oldTxn.reference:p.reference,parentTxnId:oldTxn.txn_id,reason});purchaseTxnId=nt.txn_id;up.amount=newPrincipal;up.total_invested=newTotal;up.purchase_txn_id=purchaseTxnId}await update(T.INVESTMENTS,'investment_id',investmentId,up);await rpc('nd_ensure_profit_source_for_investment',{p_user_id:s.userId,p_investment_id:investmentId,p_name:p.name||inv.name,p_category:asStatus(p.type||inv.type,'OTHER')});await audit(s.userId,'UPDATE','INVESTMENT',investmentId,inv,up,reason);return {ok:true,investmentId,reversalTxnId,purchaseTxnId}}
