async function editInvestmentReturn(token:string,returnId:string,p:A={},reason=''){const s=await sessionFromToken(token);requireAny(s,'investments.edit','accounts.edit');if(!reason)throw new Error('Modification reason required.');const r=await one(T.INVESTMENT_RETURNS,'return_id',returnId);if(!r||!await investmentReturnEffective(r))throw new Error('Investment return not found.');const t=await one(T.TRANSACTIONS,'txn_id',r.txn_id);if(!t)throw new Error('Return transaction missing.');await reverseInvestmentReturn(token,returnId,reason);const replacement=await recordInvestmentReturn(token,{investmentId:r.investment_id,type:asStatus(p.type||r.type),amount:round2(p.amount===undefined?r.amount:p.amount),date:p.date||r.return_date,accountId:p.accountId||t.payment_account_id,paymentMethod:p.paymentMethod||t.payment_method,reference:p.reference===undefined?t.reference:p.reference,notes:p.notes===undefined?r.notes:p.notes,periodType:p.periodType,periodStart:p.periodStart,periodEnd:p.periodEnd,month:p.month,year:p.year,quarter:p.quarter,half:p.half,markCompleted:p.markCompleted,parentTxnId:t.txn_id,parentReturnId:r.return_id,reason});await audit(s.userId,'CORRECT','INVESTMENT_RETURN',returnId,r,replacement,reason);return {ok:true,replacement}}
async function reverseInvestmentClosure(token:string,closureId:string,reason:string){const s=await sessionFromToken(token);requireAny(s,'investments.edit','accounts.edit');if(!reason)throw new Error('Reversal reason required.');const c=await one(T.INVESTMENT_CLOSURES,'closure_id',closureId);if(!c||asStatus(c.status)!=='POSTED')throw new Error('Active investment closure not found.');if(c.profit_id&&await reservedProfitAmount(c.profit_id)>0)throw new Error('Reverse/cancel the related profit distribution first.');const t=await one(T.TRANSACTIONS,'txn_id',c.txn_id);if(!t)throw new Error('Closure transaction missing.');const rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.INVESTMENT_CLOSURES,'closure_id',closureId,{status:'REVERSED',updated_at:now(),updated_by:s.userId});if(c.profit_id)await update(T.PROFIT_RECORDS,'profit_id',c.profit_id,{status:'REVERSED',undistributed_amount:0,updated_at:now(),updated_by:s.userId});await update(T.INVESTMENTS,'investment_id',c.investment_id,{status:'ACTIVE',closure_id:'',closed_at:null,selling_amount:0,closing_reference:'',close_notes:'',closed_by:'',updated_at:now(),updated_by:s.userId});await rpc('nd_refresh_investment_summary',{p_investment_id:c.investment_id,p_user_id:s.userId});await audit(s.userId,'REVERSE','INVESTMENT_CLOSURE',closureId,c,{reversalTxnId:rev},reason);return {ok:true,reversalTxnId:rev}}
async function cancelInvestment(token:string,investmentId:string,reason:string){const s=await sessionFromToken(token);requireAny(s,'investments.edit');if(!reason)throw new Error('Cancellation reason required.');const inv=await one(T.INVESTMENTS,'investment_id',investmentId);if(!inv||!['ACTIVE','PARTIALLY_RETURNED','PRINCIPAL_RETURNED'].includes(asStatus(inv.status)))throw new Error('Open investment not found.');if((await investmentReturns(investmentId)).length||await investmentActiveClosure(investmentId))throw new Error('Reverse all returns/closure before cancelling this investment.');const t=await one(T.TRANSACTIONS,'txn_id',inv.purchase_txn_id);if(!t)throw new Error('Purchase transaction missing.');const rev=await reverseTxn(s,t.txn_id,reason);await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.INVESTMENTS,'investment_id',investmentId,{status:'CANCELLED',updated_at:now(),updated_by:s.userId});await audit(s.userId,'CANCEL','INVESTMENT',investmentId,inv,{reversalTxnId:rev},reason);return {ok:true,reversalTxnId:rev}}
async function getInvestmentDetails(token:string,id:string){const s=await sessionFromToken(token);if(!(hasPerm(s,'investments.view')||s.role==='ADMIN'))throw new Error('PERMISSION_DENIED');const inv=await one(T.INVESTMENTS,'investment_id',id);if(!inv)throw new Error('Investment not found.');const refreshed:any=await rpc('nd_refresh_investment_summary',{p_investment_id:id,p_user_id:'SYSTEM_READ'});return {investment:legacy(refreshed||inv),returns:upperRows(await many(T.INVESTMENT_RETURNS,{investment_id:id},1000,'return_date')),closure:legacy(await investmentActiveClosure(id)),closureHistory:upperRows(await many(T.INVESTMENT_CLOSURES,{investment_id:id},1000,'created_at')),profitRecords:upperRows(await many(T.PROFIT_RECORDS,{investment_id:id},1000,'profit_date')),documents:upperRows(await many(T.DOCUMENTS,{related_id:id},1000))}}
async function listUsers(token:string){const s=await sessionFromToken(token);requireAdmin(s);const rows=await many(T.USERS,{},5000);return rows.map((u:A)=>({userId:u.user_id,memberId:u.member_id,name:u.full_name,username:u.username,role:u.role_id,status:u.status,mustChange:!!u.must_change_password,lastLogin:u.last_login_at,createdAt:u.created_at}))}
async function createStaffUser(token:string,p:A={}){const s=await sessionFromToken(token);requireAdmin(s);if(!String(p.name||'').trim()||!String(p.username||'').trim())throw new Error('Name and username required.');const uname=String(p.username).trim().toLowerCase();if(!/^[a-z0-9._-]{3,40}$/.test(uname))throw new Error('Username must be 3-40 letters, numbers, dot, underscore or hyphen.');if(await one(T.USERS,'username',uname))throw new Error('Username already exists.');const role=asStatus(p.role,'STAFF'),rr=await one(T.ROLES,'role_id',role);if(!rr||rr.status!=='ACTIVE'||role==='MEMBER')throw new Error('Invalid staff role.');const temp=randomPassword();const {data:au,error}=await sb().auth.admin.createUser({email:authEmail(uname),password:temp,email_confirm:true,user_metadata:{username:uname}});if(error||!au.user)throw error||new Error('Could not create staff login.');const id=await nextId('USER','USR-',6);try{await insert(T.USERS,{user_id:id,member_id:'',full_name:String(p.name).trim().slice(0,120),username:uname,password_hash:'',salt:'',role_id:role,status:'ACTIVE',must_change_password:true,last_login_at:null,created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId,auth_uid:au.user.id});await audit(s.userId,'CREATE','USER',id,{}, {name:p.name,username:uname,role},'Staff user created');return {ok:true,userId:id,username:uname,tempPassword:temp}}catch(e){try{await sb().auth.admin.deleteUser(au.user.id)}catch{}throw e}}
async function updateUser(token:string,userId:string,p:A={},reason=''){const s=await sessionFromToken(token);requireAdmin(s);const u=await one(T.USERS,'user_id',userId);if(!u)throw new Error('User not found.');const up:A={updated_at:now(),updated_by:s.userId};let securityChanged=false;if(p.name!==undefined){if(!String(p.name||'').trim())throw new Error('Name required.');up.full_name=String(p.name).trim().slice(0,120)}if(p.role!==undefined){const role=asStatus(p.role),rr=await one(T.ROLES,'role_id',role);if(!rr||rr.status!=='ACTIVE')throw new Error('Invalid role.');up.role_id=role;securityChanged=role!==u.role_id}if(p.status!==undefined){const st=asStatus(p.status);if(!['ACTIVE','INACTIVE','SUSPENDED'].includes(st))throw new Error('Invalid user status.');up.status=st;securityChanged=securityChanged||st!==u.status}const demoting=u.role_id==='ADMIN'&&((up.role_id&&up.role_id!=='ADMIN')||(up.status&&up.status!=='ACTIVE'));if(demoting){const admins=(await many(T.USERS,{role_id:'ADMIN'},500)).filter((x:A)=>x.status==='ACTIVE'&&x.user_id!==userId);if(!admins.length)throw new Error('The last active administrator cannot be deactivated or demoted.')}await update(T.USERS,'user_id',userId,up);const revoked=securityChanged?await revokeUserSessions(userId):0;await audit(s.userId,'UPDATE','USER',userId,u,{...up,REVOKED_SESSIONS:revoked},reason||'User updated');return {ok:true,revokedSessions:revoked}}
async function listRoles(token:string){await sessionFromToken(token);const rows=await many(T.ROLES,{},500);return rows.map((r:A)=>({id:r.role_id,name:r.role_name,permissions:Array.isArray(r.permissions_json)?r.permissions_json:json(r.permissions_json,[]),status:r.status}))}
async function saveRolePermissions(token:string,roleId:string,permissions:A[]){const s=await sessionFromToken(token);requireAdmin(s);const r=await one(T.ROLES,'role_id',roleId);if(!r)throw new Error('Role not found.');const clean=[...new Set((Array.isArray(permissions)?permissions:[]).map(x=>String(x||'').trim()).filter(x=>x&&x.length<=100))];const final=roleId==='ADMIN'?['*']:clean;await update(T.ROLES,'role_id',roleId,{permissions_json:final,updated_at:now()});let revoked=0;for(const u of await many(T.USERS,{role_id:roleId},1000))revoked+=await revokeUserSessions(u.user_id);await audit(s.userId,'PERMISSIONS','ROLE',roleId,{permissions:r.permissions_json},{permissions:final,revokedSessions:revoked},'Role permissions updated');return {ok:true,revokedSessions:revoked}}
async function listMeetings(token:string){const s=await sessionFromToken(token);if(!(hasPerm(s,'meetings.view')||s.role==='ADMIN'))throw new Error('PERMISSION_DENIED');return upperRows(await many(T.MEETINGS,{},300,'date'))}
async function saveMeeting(token:string,p:A={}){const s=await sessionFromToken(token);requireAny(s,'meetings.edit');const title=String(p.title||'').trim().slice(0,200),date=dateOnly(p.date);if(!title||!date)throw new Error('Meeting title and date required.');const status=asStatus(p.status,'SCHEDULED');if(!['SCHEDULED','COMPLETED','CANCELLED','POSTPONED'].includes(status))throw new Error('Invalid meeting status.');const id=p.meetingId||await nextId('MEETING','MTG-',7);if(p.meetingId){const r=await one(T.MEETINGS,'meeting_id',id);if(!r)throw new Error('Meeting not found.');const up={type:p.type||r.type,title,date,time:p.time||'',venue:p.venue||'',agenda:p.agenda||'',minutes:p.minutes||'',resolution_no:p.resolutionNo||'',status:p.status?status:r.status,updated_at:now(),updated_by:s.userId};await update(T.MEETINGS,'meeting_id',id,up);await audit(s.userId,'UPDATE','MEETING',id,r,up,'Meeting updated')}else{const row={meeting_id:id,type:p.type||'GENERAL',title,date,time:p.time||'',venue:p.venue||'',agenda:p.agenda||'',minutes:p.minutes||'',resolution_no:p.resolutionNo||'',status,created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId};await insert(T.MEETINGS,row);await audit(s.userId,'CREATE','MEETING',id,{},row,'Meeting created')}return {ok:true,meetingId:id}}
async function listMeetingAttendance(token:string,meetingId:string){const s=await sessionFromToken(token);requireAny(s,'meetings.view');if(!await one(T.MEETINGS,'meeting_id',meetingId))throw new Error('Meeting not found.');return upperRows(await many(T.MEETING_ATTENDANCE,{meeting_id:meetingId},5000))}
async function saveMeetingAttendance(token:string,meetingId:string,items:A[]=[]){const s=await sessionFromToken(token);requireAny(s,'meetings.edit');if(!await one(T.MEETINGS,'meeting_id',meetingId))throw new Error('Meeting not found.');let saved=0;for(const x of items||[]){if(!x?.memberId||!await one(T.MEMBERS,'member_id',x.memberId))continue;const st=asStatus(x.status,'PRESENT');if(!['PRESENT','ABSENT','EXCUSED'].includes(st))throw new Error('Invalid attendance status.');const {data:existing,error}=await sb().from(T.MEETING_ATTENDANCE).select('*').eq('meeting_id',meetingId).eq('member_id',x.memberId).maybeSingle();if(error)throw error;if(existing)await update(T.MEETING_ATTENDANCE,'attendance_id',existing.attendance_id,{status:st,note:String(x.note||'').slice(0,500),updated_at:now(),updated_by:s.userId});else await insert(T.MEETING_ATTENDANCE,{attendance_id:await nextId('ATTENDANCE','ATD-',8),meeting_id:meetingId,member_id:x.memberId,status:st,note:String(x.note||'').slice(0,500),created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId});saved++}await audit(s.userId,'UPDATE','MEETING_ATTENDANCE',meetingId,{}, {saved},'Meeting attendance saved');return {ok:true,count:saved}}
async function listCommittee(token:string){const s=await sessionFromToken(token);if(!(hasPerm(s,'committee.view')||hasPerm(s,'members.view')||s.role==='ADMIN'))throw new Error('PERMISSION_DENIED');return upperRows(await many(T.COMMITTEE,{},5000))}
async function addCommitteeMember(token:string,p:A={}){const s=await sessionFromToken(token);requireAny(s,'committee.edit');const m=await one(T.MEMBERS,'member_id',p.memberId);if(!m)throw new Error('Member not found.');const designation=String(p.designation||'').trim().slice(0,120);if(!designation)throw new Error('Designation required.');const start=dateOnly(p.startDate||today()),end=dateOnly(p.endDate||'');if(end&&end<start)throw new Error('Committee end date cannot be before start date.');const st=asStatus(p.status,'ACTIVE');if(!['ACTIVE','INACTIVE','COMPLETED'].includes(st))throw new Error('Invalid committee status.');const id=await nextId('COMMITTEE','COM-',6),row={committee_id:id,member_id:m.member_id,designation,start_date:start,end_date:end||null,status:st,notes:String(p.notes||'').slice(0,1000),created_at:now(),created_by:s.userId};await insert(T.COMMITTEE,row);await audit(s.userId,'CREATE','COMMITTEE',id,{},p,'Committee member added');return {ok:true,committeeId:id}}
async function uploadDocument(token:string,p:A={}){const s=await sessionFromToken(token);let memberId=String(p.memberId||''),relatedType=asStatus(p.relatedType,'MEMBER'),relatedId=String(p.relatedId||memberId);if(!memberId&&!relatedId&&relatedType==='MEMBER')relatedType='OTHER';if(s.role==='MEMBER'){if(p.memberId&&p.memberId!==s.memberId)throw new Error('PERMISSION_DENIED');memberId=s.memberId;relatedType='MEMBER';relatedId=s.memberId}else requireAny(s,'documents.edit');const title=String(p.title||'').trim().slice(0,160);if(!p.dataUrl||!title)throw new Error('Document and title required.');if(!['MEMBER','LOAN','INVESTMENT','MEETING','OTHER'].includes(relatedType))throw new Error('Invalid related document type.');if(memberId&&!await one(T.MEMBERS,'member_id',memberId))throw new Error('Related member not found.');const lookup:A={MEMBER:[T.MEMBERS,'member_id'],LOAN:[T.LOANS,'loan_id'],INVESTMENT:[T.INVESTMENTS,'investment_id'],MEETING:[T.MEETINGS,'meeting_id']};if(relatedType!=='OTHER'&&relatedId){const [tb,col]=lookup[relatedType];if(!await one(tb,col,relatedId))throw new Error('Related '+relatedType.toLowerCase()+' record not found.')}const f=await storeDataUrl(p.dataUrl,'documents',(memberId||relatedId||'doc')+'_'+Date.now()),id=await nextId('DOCUMENT','DOC-',8);await insert(T.DOCUMENTS,{document_id:id,member_id:memberId,related_type:relatedType,related_id:relatedId,title,file_id:f.path,file_name:p.fileName||f.name,mime_type:f.mime,status:'ACTIVE',created_at:now(),created_by:s.userId});await audit(s.userId,'UPLOAD','DOCUMENT',id,{}, {title,memberId,relatedType,relatedId},'Document uploaded');return {ok:true,documentId:id}}
async function listDocuments(token:string,filters:A={}){const s=await sessionFromToken(token);let rows=(await many(T.DOCUMENTS,{status:'ACTIVE'},1000,'created_at'));if(s.role==='MEMBER')rows=rows.filter((r:A)=>r.member_id===s.memberId);else requireAny(s,'documents.view');if(filters.memberId)rows=rows.filter((r:A)=>r.member_id===filters.memberId);if(filters.relatedId)rows=rows.filter((r:A)=>r.related_id===filters.relatedId);return rows.slice(0,300).map((r:A)=>({documentId:r.document_id,memberId:r.member_id,relatedType:r.related_type,relatedId:r.related_id,title:r.title,fileName:r.file_name,mimeType:r.mime_type,createdAt:r.created_at}))}
async function getDocumentData(token:string,documentId:string){const s=await sessionFromToken(token),d=await one(T.DOCUMENTS,'document_id',documentId);if(!d)throw new Error('Document not found.');if(s.role==='MEMBER'&&d.member_id!==s.memberId)throw new Error('PERMISSION_DENIED');if(s.role!=='MEMBER')requireAny(s,'documents.view');return {title:d.title,fileName:d.file_name,mimeType:d.mime_type,dataUri:await storageDataUri('documents',d.file_id)}}
async function listNotifications(token:string){const s=await sessionFromToken(token);const rows=await many(T.NOTIFICATIONS,{},1000,'created_at');return upperRows(rows.filter((n:A)=>(n.user_id&&n.user_id===s.userId)||(!n.user_id&&n.member_id&&n.member_id===s.memberId)||(!n.user_id&&!n.member_id)).slice(0,100))}
async function markNotificationRead(token:string,id:string){const s=await sessionFromToken(token),n=await one(T.NOTIFICATIONS,'notification_id',id);if(!n)throw new Error('Notification not found.');if(s.role!=='ADMIN'&&((n.user_id&&n.user_id!==s.userId)||(n.member_id&&n.member_id!==s.memberId)))throw new Error('PERMISSION_DENIED');await update(T.NOTIFICATIONS,'notification_id',id,{status:'READ',read_at:now()});return {ok:true}}
async function createBroadcastNotification(token:string,p:A={}){const s=await sessionFromToken(token);requireAdmin(s);const title=String(p.title||'').trim().slice(0,160),message=String(p.message||'').trim().slice(0,2000);if(!title||!message)throw new Error('Title and message required.');if(p.memberId){if(!await one(T.MEMBERS,'member_id',p.memberId))throw new Error('Member not found.');await notify(p.memberId,p.type||'NOTICE',title,message)}else{const users=(await many(T.USERS,{status:'ACTIVE'},5000));for(const u of users)await insert(T.NOTIFICATIONS,{notification_id:await nextId('NOTIFICATION','NTF-',7),user_id:u.user_id,member_id:u.member_id||'',type:p.type||'NOTICE',title,message,status:'UNREAD',created_at:now(),read_at:null})}await audit(s.userId,'CREATE','NOTIFICATION',p.memberId||'ALL',{}, {title,message},'Notification');return {ok:true}}
async function getAuditLog(token:string,options:A={}){const s=await sessionFromToken(token);requireAny(s,'audit.view');let rows=await many(T.AUDIT_LOG,{},Math.min(1000,num(options.limit||300)),'created_at');if(options.entityType)rows=rows.filter((r:A)=>r.entity_type===options.entityType);if(options.userId)rows=rows.filter((r:A)=>r.user_id===options.userId);return upperRows(rows)}

