function validateConfig(spec:A,value:A){let raw=String(value??'').trim();if(spec.required&&!raw)throw new Error(spec.label+' is required.');if(!raw)return '';if(spec.type==='text')return raw;if(spec.type==='year'){const n=Number(raw);if(!/^\d{4}$/.test(raw)||n<1900||n>2200)throw new Error('Establishment Year must be 1900-2200.');return String(Math.floor(n))}if(spec.type==='monthKey'){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(raw))throw new Error('Society Start Month must use YYYY-MM.');return raw}if(spec.type==='email')return normalizeEmail(raw);if(spec.type==='mobile')return normalizeMobile(raw,false);if(spec.type==='prefix'){raw=raw.toUpperCase();if(!/^[A-Z0-9][A-Z0-9-]{0,19}$/.test(raw))throw new Error(spec.label+' may contain A-Z, 0-9 and hyphen only (max 20).');return raw}if(spec.type==='select'){raw=raw.toUpperCase();if(!spec.options.includes(raw))throw new Error(spec.label+' is not supported.');return raw}if(spec.type==='timezone'){if(!/^[A-Za-z_]+(?:\/[A-Za-z0-9_+.-]+)+$/.test(raw))throw new Error('Timezone must be a valid IANA name, for example Asia/Dhaka.');try{new Intl.DateTimeFormat('en',{timeZone:raw}).format()}catch{throw new Error('Timezone is not supported.')}return raw}if(spec.type==='currency'){if(raw.length>6)throw new Error('Currency Symbol must be 1-6 characters.');return raw}const n=Number(raw);if(!Number.isFinite(n))throw new Error(spec.label+' must be a valid number.');if(spec.type==='percent'&&(n<0||n>100))throw new Error(spec.label+' must be between 0 and 100.');if(spec.type==='monthNumber'&&(n<1||n>12||Math.floor(n)!==n))throw new Error(spec.label+' must be between 1 and 12.');if(spec.type==='dueDay'&&(n<1||n>31||Math.floor(n)!==n))throw new Error(spec.label+' must be between 1 and 31.');if(spec.type==='positiveMoney'&&n<=0)throw new Error(spec.label+' must be greater than 0.');if(spec.type==='money'&&n<0)throw new Error(spec.label+' cannot be negative.');if(spec.type==='nonNegativeNumber'&&n<0)throw new Error(spec.label+' cannot be negative.');if(spec.type==='nonNegativeInt'&&(n<0||Math.floor(n)!==n))throw new Error(spec.label+' must be a whole number of 0 or more.');if(spec.type==='positiveInt'&&(n<=0||Math.floor(n)!==n))throw new Error(spec.label+' must be a positive whole number.');return String(n)}
async function getSettings(token:string){const s=await sessionFromToken(token);requireAdmin(s);const rows=await many(T.CONFIG,{},500),by=Object.fromEntries(rows.map((r:A)=>[r.key,r]));const audits=(await many(T.AUDIT_LOG,{entity_type:'CONFIG',action:'CONFIG_CHANGE'},2000,'created_at')),previous:A={};for(const a of audits)if(!(a.entity_id in previous)){const ov=json(a.old_value,a.old_value);previous[a.entity_id]=typeof ov==='string'?ov:(ov??'')}return CONFIG_FIELDS.map(spec=>{const r=by[spec.key]||{},can=Object.prototype.hasOwnProperty.call(previous,spec.key);return {key:spec.key,category:spec.category,label:spec.label,type:spec.type,required:!!spec.required,options:spec.options||[],financial:!!spec.financial,value:r.value===undefined?'':String(r.value),description:r.description||'',updatedAt:r.updated_at||'',updatedBy:r.updated_by||'',canRestore:can,previousValue:can?String(previous[spec.key]):''}})}
async function saveSettings(token:string,items:A[],reason:string,financialConfirmation:boolean){const s=await sessionFromToken(token);requireAdmin(s);reason=String(reason||'').trim();if(!reason)throw new Error('Change Reason is required.');const specs=Object.fromEntries(CONFIG_FIELDS.map(x=>[x.key,x])),current=await configMap(),validated:A={},seen=new Set<string>();for(const x of items||[]){const key=String(x?.key||'');if(!specs[key])throw new Error('CONFIG key is not editable: '+key);if(seen.has(key))throw new Error('Duplicate CONFIG key submitted: '+key);seen.add(key);validated[key]=validateConfig(specs[key],x.value)}for(const spec of CONFIG_FIELDS){if(!(spec.key in validated))validated[spec.key]=String(current[spec.key]??'');if(spec.required)validated[spec.key]=validateConfig(spec,validated[spec.key])}const prefixes=['MEMBER_ID_PREFIX','RECEIPT_PREFIX','VOUCHER_PREFIX'].map(k=>validated[k]);if(new Set(prefixes).size!==prefixes.length)throw new Error('Member, Receipt and Voucher prefixes must be different.');const changes=Object.keys(validated).filter(k=>String(current[k]??'')!==String(validated[k])).map(k=>({key:k,oldValue:String(current[k]??''),newValue:String(validated[k]),spec:specs[k]}));if(!changes.length)return {ok:true,changed:0,message:'No settings changed.'};const financial=changes.filter(x=>x.spec.financial);if(financial.length&&financialConfirmation!==true)throw new Error('Financial change confirmation is required.');const startChange=changes.find(x=>x.key==='SOCIETY_START_MONTH');if(startChange&&startChange.newValue>startChange.oldValue){const dues=await many(T.MONTHLY_DUES,{},10000);if(dues.some((d:A)=>asStatus(d.status)!=='MERGED'&&String(d.due_month)<startChange.newValue))throw new Error('Society Start Month cannot be moved later while earlier due records exist. Review/reconcile those obligations first.')}for(const c of changes){await setConfig(c.key,c.newValue,s.userId);await audit(s.userId,'CONFIG_CHANGE','CONFIG',c.key,c.oldValue,c.newValue,reason)}const effects:A={};const amt=changes.find(x=>x.key==='MONTHLY_UNIT_AMOUNT');if(amt){const eff=addMonthsKey(monthKey(),1)+'-01';let n=0;for(const m of (await many(T.MEMBERS,{},5000)).filter((x:A)=>x.status!=='CLOSED')){const u:any=await rpc('nd_savings_unit_for_month',{p_member_id:m.member_id,p_month:eff.slice(0,7)});if(!u||num(u.unit_amount)===num(amt.newValue))continue;await rpc('nd_change_savings_units',{p_user_id:s.userId,p_member_id:m.member_id,p_units:Math.max(1,Math.floor(num(u.units))),p_effective_from:eff,p_reason:'Monthly unit amount configuration effective for future dues'});const latest=await currentUnit(m.member_id,eff);if(latest)await update(T.SAVINGS_UNITS,'unit_id',latest.UNIT_ID,{unit_amount:num(amt.newValue),updated_at:now(),updated_by:s.userId});n++}effects.monthlyUnitAmount={effectiveMonth:eff.slice(0,7),membersScheduled:n}}if(startChange&&startChange.newValue<startChange.oldValue){let processed=0,baselines=0;const units=await many(T.SAVINGS_UNITS,{},10000);for(const m of await many(T.MEMBERS,{},5000)){const ur=units.filter((u:A)=>u.member_id===m.member_id&&u.status==='ACTIVE').sort((a:A,b:A)=>String(a.effective_from).localeCompare(String(b.effective_from)));if(ur[0]&&monthOnly(ur[0].effective_from)>startChange.newValue){await update(T.SAVINGS_UNITS,'unit_id',ur[0].unit_id,{effective_from:startChange.newValue+'-01',updated_at:now(),updated_by:s.userId,notes:(String(ur[0].notes||'')+' | Baseline aligned to society start '+startChange.newValue).slice(0,1000)});baselines++}await rpc('nd_ensure_member_dues_through',{p_member_id:m.member_id,p_end_month:monthKey(),p_user_id:s.userId});await rpc('nd_reconcile_savings_dues',{p_member_id:m.member_id,p_user_id:s.userId});processed++}effects.societyStart={membersEvaluated:processed,unitBaselinesUpdated:baselines}}return {ok:true,changed:changes.length,keys:changes.map(x=>x.key),financialKeys:financial.map(x=>x.key),effects,message:financial.length?'এই পরিবর্তন ভবিষ্যতের নতুন লেনদেনে কার্যকর হবে। পূর্বে সম্পন্ন লেনদেন স্বয়ংক্রিয়ভাবে পরিবর্তিত হবে না।':'Settings saved.'}}
async function getConfigValidationReport(token:string){const s=await sessionFromToken(token);requireAdmin(s);const cm=await configMap(),errors:A[]=[],warnings:A[]=[];for(const spec of CONFIG_FIELDS)try{validateConfig(spec,cm[spec.key])}catch(e:A){errors.push({key:spec.key,message:e.message})}const prefixes=['MEMBER_ID_PREFIX','RECEIPT_PREFIX','VOUCHER_PREFIX'].map(k=>cm[k]);if(new Set(prefixes).size!==prefixes.length)errors.push({key:'PREFIXES',message:'Member, Receipt and Voucher prefixes must be different.'});if(!cm.SOCIETY_EMAIL)warnings.push({key:'SOCIETY_EMAIL',message:'Optional email is blank.'});if(!cm.SOCIETY_MOBILE)warnings.push({key:'SOCIETY_MOBILE',message:'Optional society mobile is blank.'});return {ok:!errors.length,checked:CONFIG_FIELDS.length,errors,warnings}}
async function createBackup(token:string){const s=await sessionFromToken(token);requireAny(s,'backup.manage');const tables=Object.values(T),snapshot:A={meta:{createdAt:now(),version:'1.1.6',database:'Supabase/PostgreSQL'},tables:{}};for(const table of tables){snapshot.tables[table]=await many(table,{},20000)}const id=await nextId('BACKUP','BKP-',7),file=`${today()}/${id}_${Date.now()}.json`,buf=Buffer.from(JSON.stringify(snapshot));const {error}=await sb().storage.from('backups').upload(file,buf,{contentType:'application/json',upsert:false});if(error)throw error;await insert(T.BACKUPS,{backup_id:id,file_id:file,file_name:file.split('/').pop(),created_at:now(),created_by:s.userId,status:'SUCCESS'});await audit(s.userId,'BACKUP','BACKUP',id,{}, {file},'Database logical backup');return {ok:true,backupId:id,fileName:file.split('/').pop()}}
async function listBackups(token:string){const s=await sessionFromToken(token);requireAny(s,'backup.manage');return (await many(T.BACKUPS,{},100,'created_at')).map((b:A)=>({backupId:b.backup_id,fileName:b.file_name,createdAt:b.created_at,createdBy:b.created_by,status:b.status}))}
async function getReportFilterOptions(token:string){const s=await sessionFromToken(token);if(s.role==='MEMBER'||!hasPerm(s,'reports.view'))throw new Error('PERMISSION_DENIED');return {members:(await many(T.MEMBERS,{},1000,'created_at')).map((m:A)=>({memberId:m.member_id,nameBn:m.name_bn,nameEn:m.name_en,status:m.status})),investments:(await many(T.INVESTMENTS,{},500,'created_at')).map((i:A)=>({INVESTMENT_ID:i.investment_id,NAME:i.name,TYPE:i.type,STATUS:i.status})),sources:(await many(T.PROFIT_SOURCES,{},500,'created_at')).map((p:A)=>({SOURCE_ID:p.source_id,SOURCE_NAME:p.source_name,CATEGORY:p.category,STATUS:p.status}))}}
const REPORT_TABLE:A={MEMBERS:T.MEMBERS,DUES:T.MONTHLY_DUES,TRANSACTIONS:T.TRANSACTIONS,LOANS:T.LOANS,INVESTMENTS:T.INVESTMENTS,INCOME:T.INCOME,EXPENSES:T.EXPENSES,EXPENSE_ALLOCATIONS:T.EXPENSE_ALLOCATIONS,GENERAL_LEDGER:T.GENERAL_LEDGER,RECEIPTS:T.RECEIPTS,VOUCHERS:T.VOUCHERS,LOAN_SCHEDULE:T.LOAN_SCHEDULE,GUARANTORS:T.GUARANTORS,INVESTMENT_RETURNS:T.INVESTMENT_RETURNS,BANK_ACCOUNTS:T.BANK_ACCOUNTS,MEETINGS:T.MEETINGS,MEETING_ATTENDANCE:T.MEETING_ATTENDANCE,COMMITTEE:T.COMMITTEE,INVESTMENT_CLOSURES:T.INVESTMENT_CLOSURES,PROFIT_SOURCES:T.PROFIT_SOURCES,PROFIT_RECORDS:T.PROFIT_RECORDS,PROFIT_DISTRIBUTIONS:T.PROFIT_DISTRIBUTIONS,PROFIT_DISTRIBUTION:T.PROFIT_DISTRIBUTION};
async function getReports(token:string,type:string,filters:A={}){const s=await sessionFromToken(token);if(s.role==='MEMBER'||!hasPerm(s,'reports.view'))throw new Error('PERMISSION_DENIED');type=asStatus(type,'MEMBERS');const table=REPORT_TABLE[type];if(!table)throw new Error('Unknown report type.');let rows=await many(table,{},5000);if(filters.memberId)rows=rows.filter((r:A)=>r.member_id===filters.memberId);if(filters.investmentId)rows=rows.filter((r:A)=>r.investment_id===filters.investmentId||r.related_id===filters.investmentId);if(filters.sourceId)rows=rows.filter((r:A)=>r.source_id===filters.sourceId);if(filters.category)rows=rows.filter((r:A)=>r.category===filters.category||r.type===filters.category);if(filters.status)rows=rows.filter((r:A)=>r.status===filters.status);const start=(r:A)=>dateOnly(r.date||r.txn_date||r.receipt_date||r.application_date||r.due_date||r.entry_date||r.return_date||r.close_date||r.profit_date||r.period_start||r.join_date||r.start_date||r.created_at||''),end=(r:A)=>dateOnly(r.period_end||start(r));if(filters.month)rows=rows.filter((r:A)=>start(r).slice(0,7)===filters.month);if(filters.year)rows=rows.filter((r:A)=>start(r).slice(0,4)===String(filters.year));if(filters.from)rows=rows.filter((r:A)=>end(r)>=filters.from);if(filters.to)rows=rows.filter((r:A)=>start(r)<=filters.to);return upperRows(rows.slice(0,3000))}

/* ===== ProfitService v1.1.6 parity ===== */
function canViewProfit(s:LegacySession){return s.role==='ADMIN'||hasPerm(s,'profits.view')||hasPerm(s,'accounts.view')||hasPerm(s,'investments.view')}
function canEditProfit(s:LegacySession){return s.role==='ADMIN'||hasPerm(s,'profits.edit')||hasPerm(s,'accounts.edit')}
function requireProfitView(s:LegacySession){if(!canViewProfit(s))throw new Error('PERMISSION_DENIED')}
function requireProfitEdit(s:LegacySession){if(!canEditProfit(s))throw new Error('PERMISSION_DENIED')}

async function ensureProfitSourceForInvestment(s:LegacySession,investmentId:string,name?:string,category?:string){
  const inv=await one(T.INVESTMENTS,'investment_id',investmentId);if(!inv)throw new Error('Investment not found.');
  return rpc('nd_ensure_profit_source_for_investment',{p_user_id:s.userId,p_investment_id:investmentId,p_name:name||inv.name,p_category:category||inv.type});
}
async function ensureLegacyProfitSource(s:LegacySession){
  const {data,error}=await sb().from(T.PROFIT_SOURCES).select('*').eq('project_reference','LEGACY_GENERAL').limit(1);if(error)throw error;if(data?.[0])return data[0];
  return insert(T.PROFIT_SOURCES,{source_id:await nextId('PROFIT_SOURCE','PSR-',6),source_name:'General / Legacy Profit',category:'OTHER',investment_id:'',project_reference:'LEGACY_GENERAL',description:'Migrated yearly profit distributions',status:'ACTIVE',created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId});
}
async function ensureLegacyProfitRecord(s:LegacySession,financialYear:A,amount:A){
  const label=String(financialYear||today().slice(0,4));
  const {data,error}=await sb().from(T.PROFIT_RECORDS).select('*').eq('period_type','YEARLY').eq('period_label',label).eq('reference','LEGACY_DISTRIBUTION').limit(1);if(error)throw error;
  if(data?.[0]){const p=data[0];if(num(p.amount)+0.01<num(amount))await update(T.PROFIT_RECORDS,'profit_id',p.profit_id,{amount:round2(amount),undistributed_amount:round2(amount),updated_at:now(),updated_by:s.userId});return p.profit_id}
  const source=await ensureLegacyProfitSource(s);return String(await rpc('nd_create_profit_record_core',{p_user_id:s.userId,p_payload:{sourceId:source.source_id,category:'OTHER',profitDate:label+'-12-31',amount:round2(amount),sourceTxnId:'',reference:'LEGACY_DISTRIBUTION',notes:'Legacy distribution compatibility record',periodType:'YEARLY',year:label}}));
}
async function listProfitSources(token:string,options:A={}){const s=await sessionFromToken(token);requireProfitView(s);let rows=await many(T.PROFIT_SOURCES,{},1000,'created_at');if(options.status)rows=rows.filter((r:A)=>r.status===options.status);if(options.category)rows=rows.filter((r:A)=>r.category===options.category);return upperRows(rows.slice(0,500))}
async function createProfitSource(token:string,p:A={}){const s=await sessionFromToken(token);requireProfitEdit(s);if(!p.name)throw new Error('Profit source name required.');if(p.investmentId){const source=await ensureProfitSourceForInvestment(s,p.investmentId,p.name,p.category);return {ok:true,source:legacy(source)}}const id=await nextId('PROFIT_SOURCE','PSR-',6),obj={source_id:id,source_name:p.name,category:asStatus(p.category,'OTHER'),investment_id:'',project_reference:p.projectReference||'',description:p.description||'',status:'ACTIVE',created_at:now(),created_by:s.userId,updated_at:now(),updated_by:s.userId};await insert(T.PROFIT_SOURCES,obj);await audit(s.userId,'CREATE','PROFIT_SOURCE',id,{},obj,'Profit source created');return {ok:true,source:legacy(obj)}}

async function profitAmountMaps(){
  const [allocs,headers,txns]=await Promise.all([many(T.PROFIT_DISTRIBUTION,{},20000),many(T.PROFIT_DISTRIBUTIONS,{},10000),many(T.TRANSACTIONS,{},20000)]);
  const txStatus=new Map(txns.map((t:A)=>[t.txn_id,t.status]));const approved:A={},byDist:A={};
  for(const a of allocs){if(a.status!=='APPROVED')continue;const st=a.txn_id?txStatus.get(a.txn_id):'';if(a.txn_id&&st&&!effective(st))continue;approved[a.profit_id]=round2(num(approved[a.profit_id])+num(a.amount));byDist[a.distribution_id]=round2(num(byDist[a.distribution_id])+num(a.amount))}
  const draft:A={};for(const h of headers)if(['DRAFT','PROCESSING'].includes(h.status))draft[h.profit_id]=round2(num(draft[h.profit_id])+Math.max(0,num(h.requested_amount)-num(byDist[h.distribution_id])));
  const reserved:A={};for(const k of new Set([...Object.keys(approved),...Object.keys(draft)]))reserved[k]=round2(num(approved[k])+num(draft[k]));return {approved,reserved,byDist}
}
async function listProfitRecords(token:string,options:A={}){const s=await sessionFromToken(token);requireProfitView(s);const [sources,investments,maps]=await Promise.all([many(T.PROFIT_SOURCES,{},5000),many(T.INVESTMENTS,{},5000),profitAmountMaps()]);const sm=Object.fromEntries(sources.map((x:A)=>[x.source_id,x])),im=Object.fromEntries(investments.map((x:A)=>[x.investment_id,x]));let rows=await many(T.PROFIT_RECORDS,{},5000,'profit_date');if(options.status)rows=rows.filter((r:A)=>r.status===options.status);if(options.sourceId)rows=rows.filter((r:A)=>r.source_id===options.sourceId);if(options.investmentId)rows=rows.filter((r:A)=>r.investment_id===options.investmentId);if(options.category)rows=rows.filter((r:A)=>r.category===options.category);if(options.month)rows=rows.filter((r:A)=>String(r.profit_date).slice(0,7)===options.month);if(options.year)rows=rows.filter((r:A)=>String(r.profit_date).slice(0,4)===String(options.year));if(options.from)rows=rows.filter((r:A)=>String(r.profit_date)>=options.from);if(options.to)rows=rows.filter((r:A)=>String(r.profit_date)<=options.to);return rows.slice(0,1000).map((r:A)=>{const distributed=num(maps.approved[r.profit_id]),reserved=num(maps.reserved[r.profit_id]),source=sm[r.source_id]||{},inv=im[r.investment_id]||{};return {...legacy(r),SOURCE_NAME:source.source_name||'',INVESTMENT_NAME:inv.name||'',DISTRIBUTED_AMOUNT:round2(distributed),UNDISTRIBUTED_AMOUNT:round2(Math.max(0,num(r.amount)-distributed)),AVAILABLE_AMOUNT:round2(Math.max(0,num(r.amount)-reserved))}})}
async function createProfitRecord(token:string,p:A={}){const s=await sessionFromToken(token);requireProfitEdit(s);const source=await one(T.PROFIT_SOURCES,'source_id',p.sourceId);if(!source||source.status!=='ACTIVE')throw new Error('Active profit source required.');if(round2(p.amount)<=0)throw new Error('Profit amount required.');return rpc('nd_create_profit_record',{p_user_id:s.userId,p_payload:p})}
async function updateProfitRecord(token:string,profitId:string,p:A={},reason:string){const s=await sessionFromToken(token);requireProfitEdit(s);if(!reason)throw new Error('Modification reason required.');const pr=await one(T.PROFIT_RECORDS,'profit_id',profitId);if(!pr||['REVERSED','CANCELLED'].includes(pr.status))throw new Error('Profit record not editable.');const linkedTxn=pr.source_txn_id?await one(T.TRANSACTIONS,'txn_id',pr.source_txn_id):null;if(linkedTxn&&linkedTxn.type==='INCOME'){const incomeId=pr.source_income_id||linkedTxn.related_id;if(!incomeId)throw new Error('Linked income record is missing.');const income=await one(T.INCOME,'income_id',incomeId);return updateIncome(token,incomeId,{...p,incomeType:'DISTRIBUTABLE_PROFIT',date:p.profitDate||dateOnly(pr.profit_date),note:p.notes===undefined?pr.notes:p.notes,category:income?.category||'INVESTMENT_INCOME',accountId:p.accountId||income?.account_id||linkedTxn.payment_account_id},reason)}if(await reservedProfitAmount(profitId)>0)throw new Error('Cancel/reverse related distributions before editing this profit.');const up:A={updated_at:now(),updated_by:s.userId};let source:A=null;if(p.sourceId){source=await one(T.PROFIT_SOURCES,'source_id',p.sourceId);if(!source)throw new Error('Profit source not found.');up.source_id=p.sourceId;up.investment_id=source.investment_id||'';up.category=source.category||'OTHER'}if(p.reference!==undefined)up.reference=p.reference;if(p.notes!==undefined)up.notes=p.notes;if(p.periodType||p.periodStart||p.month||p.year){const per:any=await rpc('nd_profit_period',{p_payload:{periodType:p.periodType||pr.period_type,periodStart:p.periodStart||pr.period_start,periodEnd:p.periodEnd||pr.period_end,profitDate:p.profitDate||pr.profit_date,month:p.month,year:p.year,financialYear:p.financialYear,quarter:p.quarter,half:p.half}});up.period_type=per.type;up.period_start=per.start;up.period_end=per.end;up.period_label=per.label}const amount=p.amount===undefined?num(pr.amount):round2(p.amount);if(amount<=0)throw new Error('Profit amount required.');if(Math.abs(amount-num(pr.amount))>0.009){const t=await one(T.TRANSACTIONS,'txn_id',pr.source_txn_id);if(!t||t.type!=='PROFIT_ENTRY')throw new Error('Investment-derived profit amount must be corrected from its investment return/closure.');const result:any=await correctSimpleTransaction(token,t.txn_id,amount,reason);up.amount=amount;up.undistributed_amount=amount;up.source_txn_id=result.replacementTxnId||''}await update(T.PROFIT_RECORDS,'profit_id',profitId,up);await audit(s.userId,'UPDATE','PROFIT_RECORD',profitId,pr,up,reason);return {ok:true,profitId}}
async function reverseProfitRecord(token:string,profitId:string,reason:string){const s=await sessionFromToken(token);requireProfitEdit(s);if(!reason)throw new Error('Reversal reason required.');const pr=await one(T.PROFIT_RECORDS,'profit_id',profitId);if(!pr||['REVERSED','CANCELLED'].includes(pr.status))throw new Error('Profit record not eligible.');if(await reservedProfitAmount(profitId)>0)throw new Error('Cancel/reverse all related distributions first.');const t=pr.source_txn_id?await one(T.TRANSACTIONS,'txn_id',pr.source_txn_id):null;if(t&&t.type==='INCOME')return reverseIncome(token,pr.source_income_id||t.related_id,reason);if(t&&t.type!=='PROFIT_ENTRY')throw new Error('Reverse this profit from its investment return/closure.');const result:any=t?await correctSimpleTransaction(token,t.txn_id,0,reason):{reversalTxnId:''};await update(T.PROFIT_RECORDS,'profit_id',profitId,{status:'REVERSED',distributed_amount:0,undistributed_amount:0,updated_at:now(),updated_by:s.userId});await audit(s.userId,'REVERSE','PROFIT_RECORD',profitId,pr,{reversalTxnId:result.reversalTxnId},reason);return {ok:true,reversalTxnId:result.reversalTxnId||''}}

function distributionRequest(arg1:A,arg2:A){if(arg1&&typeof arg1==='object')return {...arg1};const y=String(arg1||today().slice(0,4));return {financialYear:y,year:y,periodType:'YEARLY',amount:arg2}}
function distributionBasisType(v:A){let x=asStatus(v,'SAVINGS');if(x==='UNIT')x='UNITS';if(!['MANUAL','SAVINGS','EQUAL','UNITS'].includes(x))throw new Error('Distribution basis must be MANUAL, SAVINGS, EQUAL or UNITS.');return x}
function setExactShareRates(rows:A[],totalWeight:A){const total=num(totalWeight);if(total<=0){rows.forEach(x=>x.rate=0);return rows}const target=10000;let used=0;for(const x of rows){const weight=Math.max(0,num(x._rateWeight)),raw=target*weight/total,whole=Math.floor(raw+1e-9);x._rateMinor=whole;x._rateRemainder=raw-whole;used+=whole}const left=target-used,order=[...rows].sort((a,b)=>Number(b._rateWeight>0)-Number(a._rateWeight>0)||b._rateRemainder-a._rateRemainder||String(a.memberId).localeCompare(String(b.memberId)));for(let i=0;i<left;i++)order[i%order.length]._rateMinor++;for(const x of rows){x.rate=round2(x._rateMinor/100);delete x._rateMinor;delete x._rateRemainder;delete x._rateWeight}return rows}
function allocateProportionalDistribution(amount:A,rows:A[],totalBasis:A){const total=num(totalBasis);if(total<=0)throw new Error('Total distribution basis cannot be zero.');const target=Math.round(round2(amount)*100);let used=0;for(const x of rows){const basis=Math.max(0,num(x.basis)),raw=target*basis/total,whole=Math.floor(raw+1e-9);x._amountMinor=whole;x._amountRemainder=raw-whole;x._rateWeight=basis;used+=whole}const left=target-used,order=[...rows].sort((a,b)=>Number(b.basis>0)-Number(a.basis>0)||b._amountRemainder-a._amountRemainder||String(a.memberId).localeCompare(String(b.memberId)));for(let i=0;i<left;i++)order[i%order.length]._amountMinor++;for(const x of rows){x.amount=round2(x._amountMinor/100);delete x._amountMinor;delete x._amountRemainder}return setExactShareRates(rows,total)}
async function buildDistributionRows(amount:A,basisType:A,items:A,distributionDate:A){const type=distributionBasisType(basisType),dd=dateOnly(distributionDate||today());const members=(await many(T.MEMBERS,{},5000,'created_at',true)).filter((m:A)=>m.status==='ACTIVE'),by=Object.fromEntries(members.map((m:A)=>[m.member_id,m]));if(!members.length)throw new Error('No active members are available for distribution.');if(type==='MANUAL'){if(!items?.length)return {rows:members.map((m:A)=>({memberId:m.member_id,name:m.name_bn||m.name_en,basis:0,amount:0,rate:0,units:'',totalUnits:'',unitPercentage:''})),totalBasis:0,totalUnits:0,percentageTotal:0,allocatedAmount:0};const manual:A[]=[],seen=new Set<string>();for(const x of items){if(!x?.memberId)throw new Error('Every allocation requires a member.');if(!by[x.memberId])throw new Error('Allocation member is not active: '+x.memberId);if(seen.has(x.memberId))throw new Error('Duplicate member allocation: '+x.memberId);seen.add(x.memberId);const allocated=round2(x.amount);if(allocated<=0)throw new Error('Allocation amount must be greater than zero for '+x.memberId);manual.push({memberId:x.memberId,name:by[x.memberId].name_bn||by[x.memberId].name_en,basis:0,amount:allocated,rate:0,units:'',totalUnits:'',unitPercentage:'',_rateWeight:allocated})}const manualSum=round2(manual.reduce((z,x)=>z+x.amount,0));if(Math.abs(manualSum-num(amount))>0.009)throw new Error(`Member allocation total (${manualSum}) must equal distribution amount (${round2(amount)}).`);setExactShareRates(manual,manualSum);return {rows:manual,totalBasis:0,totalUnits:0,percentageTotal:round2(manual.reduce((z,x)=>z+x.rate,0)),allocatedAmount:manualSum}}
  const rows=await Promise.all(members.map(async(m:A)=>{let units:A='';if(type==='UNITS'){const u=await currentUnit(m.member_id,dd);units=u===null?0:num(u.UNITS);if(units<0)throw new Error('Negative savings units are not allowed for '+m.member_id+'.')}const basis=type==='EQUAL'?1:type==='UNITS'?units:Math.max(0,await memberSavings(m.member_id));return {memberId:m.member_id,name:m.name_bn||m.name_en,basis,amount:0,rate:0,units:type==='UNITS'?units:'',totalUnits:'',unitPercentage:''}}));const eligible=type==='SAVINGS'?rows.filter(x=>x.basis>0):rows,total=round2(eligible.reduce((z,x)=>z+num(x.basis),0));if(total<=0)throw new Error(type==='UNITS'?'Total units cannot be zero.':'No eligible member basis found.');allocateProportionalDistribution(amount,eligible,total);eligible.forEach(x=>{if(type==='UNITS'){x.totalUnits=total;x.unitPercentage=x.rate}});return {rows:eligible,totalBasis:total,totalUnits:type==='UNITS'?total:0,percentageTotal:round2(eligible.reduce((z,x)=>z+x.rate,0)),allocatedAmount:round2(eligible.reduce((z,x)=>z+x.amount,0))}}
async function previewProfitDistribution(token:string,arg1:A,arg2?:A){const s=await sessionFromToken(token);requireProfitEdit(s);const req=distributionRequest(arg1,arg2),amount=round2(req.amount),basisType=distributionBasisType(req.basisType),distributionDate=dateOnly(req.distributionDate||today());if(amount<=0)throw new Error('Distributable amount required.');let profitId=req.profitId,pr=profitId?await one(T.PROFIT_RECORDS,'profit_id',profitId):null;if(!pr){profitId=await ensureLegacyProfitRecord(s,req.financialYear||req.year,amount);pr=await one(T.PROFIT_RECORDS,'profit_id',profitId)}if(!pr)throw new Error('Profit record not found.');const available=round2(Math.max(0,num(pr.amount)-await reservedProfitAmount(profitId)));if(amount>available+0.009)throw new Error('Only '+available+' remains available for distribution.');const built=await buildDistributionRows(amount,basisType,req.items,distributionDate),unallocated=round2(amount-built.allocatedAmount);return {profitId,financialYear:String(pr.period_start).slice(0,4),period:pr.period_label,totalBasis:built.totalBasis,totalUnits:built.totalUnits,percentageTotal:built.percentageTotal,allocatedAmount:built.allocatedAmount,unallocatedAmount:unallocated,distributableAmount:amount,availableBefore:available,remainingAfter:round2(available-amount),basisType,distributionDate,rows:built.rows}}
async function createProfitDistributionDraft(token:string,arg1:A,arg2?:A){const s=await sessionFromToken(token);requireProfitEdit(s);const req=distributionRequest(arg1,arg2),preview=await previewProfitDistribution(token,req),pr=await one(T.PROFIT_RECORDS,'profit_id',preview.profitId);if(!pr)throw new Error('Profit record not found.');const source=await one(T.PROFIT_SOURCES,'source_id',pr.source_id),id=await nextId('PROFIT_DISTRIBUTION_HEADER','PDS-',8),stamp=now(),reference=req.reference||id,header={distribution_id:id,profit_id:pr.profit_id,source_id:pr.source_id,investment_id:pr.investment_id||'',period_type:pr.period_type,period_start:pr.period_start,period_end:pr.period_end,period_label:pr.period_label,total_profit:pr.amount,requested_amount:preview.distributableAmount,distributed_amount:0,member_count:preview.rows.length,basis_type:preview.basisType,status:'DRAFT',reference,notes:req.notes||'',approved_by:'',approved_at:null,created_at:stamp,created_by:s.userId,updated_at:stamp,updated_by:s.userId,total_basis:preview.totalBasis,total_units:preview.totalUnits||0,distribution_date:preview.distributionDate};await insert(T.PROFIT_DISTRIBUTIONS,header);const allocations:A[]=[];for(const x of preview.rows)allocations.push({dist_id:await nextId('DIST','DST-',8),financial_year:String(pr.period_start).slice(0,4),member_id:x.memberId,basis_amount:x.basis,rate:x.rate,amount:x.amount,status:'DRAFT',txn_id:'',approved_by:'',approved_at:null,created_at:stamp,created_by:s.userId,distribution_id:id,profit_id:pr.profit_id,source_id:pr.source_id,investment_id:pr.investment_id||'',period_type:pr.period_type,period_start:pr.period_start,period_end:pr.period_end,period_label:pr.period_label,reference,updated_at:stamp,updated_by:s.userId,basis_type:preview.basisType,unit_quantity:preview.basisType==='UNITS'?x.units:0,total_units:preview.basisType==='UNITS'?preview.totalUnits:0,unit_percentage:preview.basisType==='UNITS'?x.unitPercentage:0,member_name:x.name});if(allocations.length){const {error}=await sb().from(T.PROFIT_DISTRIBUTION).insert(allocations);if(error){await del(T.PROFIT_DISTRIBUTIONS,'distribution_id',id);throw error}}await audit(s.userId,'CREATE','PROFIT_DISTRIBUTION',id,{}, {header:legacy(header),source:source?.source_name||'',method:preview.basisType,totalUnits:preview.totalUnits||0},'Profit distribution draft');return {ok:true,distributionId:id,count:preview.rows.length,total:preview.distributableAmount,remaining:preview.remainingAfter,totalUnits:preview.totalUnits||0,basisType:preview.basisType}}
async function approveProfitDistribution(token:string,distributionId:string){const s=await sessionFromToken(token);requireProfitEdit(s);return rpc('nd_approve_profit_distribution',{p_user_id:s.userId,p_distribution_id:distributionId})}
async function listProfitDistributions(token:string,options:A={}){const s=await sessionFromToken(token);requireProfitView(s);const [sources,investments,maps]=await Promise.all([many(T.PROFIT_SOURCES,{},5000),many(T.INVESTMENTS,{},5000),profitAmountMaps()]);const sm=Object.fromEntries(sources.map((x:A)=>[x.source_id,x])),im=Object.fromEntries(investments.map((x:A)=>[x.investment_id,x]));let rows=await many(T.PROFIT_DISTRIBUTIONS,{},5000,'created_at');if(options.status)rows=rows.filter((r:A)=>r.status===options.status);if(options.sourceId)rows=rows.filter((r:A)=>r.source_id===options.sourceId);if(options.investmentId)rows=rows.filter((r:A)=>r.investment_id===options.investmentId);if(options.category)rows=rows.filter((r:A)=>(sm[r.source_id]||{}).category===options.category);if(options.periodType)rows=rows.filter((r:A)=>r.period_type===options.periodType);if(options.month){const ms=String(options.month).slice(0,7)+'-01',me=endOfMonth(String(options.month).slice(0,7));rows=rows.filter((r:A)=>String(r.period_start)<=me&&String(r.period_end)>=ms)}if(options.year){const ys=String(options.year)+'-01-01',ye=String(options.year)+'-12-31';rows=rows.filter((r:A)=>String(r.period_start)<=ye&&String(r.period_end)>=ys)}if(options.from)rows=rows.filter((r:A)=>String(r.period_end)>=options.from);if(options.to)rows=rows.filter((r:A)=>String(r.period_start)<=options.to);return rows.slice(0,1000).map((r:A)=>({...legacy(r),SOURCE_NAME:(sm[r.source_id]||{}).source_name||'',INVESTMENT_NAME:(im[r.investment_id]||{}).name||'',DISTRIBUTED_AMOUNT:round2(num(maps.byDist[r.distribution_id]))}))}
async function getProfitDistributionDetails(token:string,distributionId:string){const s=await sessionFromToken(token);requireProfitView(s);const h=await one(T.PROFIT_DISTRIBUTIONS,'distribution_id',distributionId);if(!h)throw new Error('Distribution not found.');const [source,profit,members,items,maps]=await Promise.all([one(T.PROFIT_SOURCES,'source_id',h.source_id),one(T.PROFIT_RECORDS,'profit_id',h.profit_id),many(T.MEMBERS,{},5000),many(T.PROFIT_DISTRIBUTION,{distribution_id:distributionId},5000),profitAmountMaps()]);const mm=Object.fromEntries(members.map((m:A)=>[m.member_id,m])),unitBased=asStatus(h.basis_type)==='UNITS';return {distribution:{...legacy(h),DISTRIBUTED_AMOUNT:round2(num(maps.byDist[distributionId])),DISTRIBUTION_DATE:h.distribution_date||dateOnly(h.approved_at||h.created_at)},source:legacy(source),profit:legacy(profit),items:items.map((r:A)=>({...legacy(r),MEMBER_NAME:r.member_name||(mm[r.member_id]||{}).name_bn||(mm[r.member_id]||{}).name_en||'',BASIS_TYPE:r.basis_type||h.basis_type||'',UNIT_QUANTITY:r.unit_quantity!==null&&r.unit_quantity!==undefined?r.unit_quantity:(unitBased?r.basis_amount:''),TOTAL_UNITS:r.total_units!==null&&r.total_units!==undefined?r.total_units:(unitBased?h.total_units||h.total_basis:''),UNIT_PERCENTAGE:r.unit_percentage!==null&&r.unit_percentage!==undefined?r.unit_percentage:(unitBased?r.rate:'')}))}}
async function cancelProfitDistribution(token:string,distributionId:string,reason:string){const s=await sessionFromToken(token);requireProfitEdit(s);if(!reason)throw new Error('Cancellation reason required.');const h=await one(T.PROFIT_DISTRIBUTIONS,'distribution_id',distributionId);if(!h||h.status!=='DRAFT')throw new Error('Only a draft distribution can be cancelled.');const {error}=await sb().from(T.PROFIT_DISTRIBUTION).update({status:'CANCELLED',updated_at:now(),updated_by:s.userId}).eq('distribution_id',distributionId);if(error)throw error;await update(T.PROFIT_DISTRIBUTIONS,'distribution_id',distributionId,{status:'CANCELLED',updated_at:now(),updated_by:s.userId});await rpc('nd_refresh_profit_record',{p_profit_id:h.profit_id,p_user_id:s.userId});await audit(s.userId,'CANCEL','PROFIT_DISTRIBUTION',distributionId,h,{status:'CANCELLED'},reason);return {ok:true}}
async function reverseProfitDistribution(token:string,distributionId:string,reason:string){const s=await sessionFromToken(token);requireProfitEdit(s);if(!reason)throw new Error('Reversal reason required.');const h=await one(T.PROFIT_DISTRIBUTIONS,'distribution_id',distributionId);if(!h||h.status!=='APPROVED')throw new Error('Only an approved distribution can be reversed.');const rows=(await many(T.PROFIT_DISTRIBUTION,{distribution_id:distributionId},5000)).filter((r:A)=>r.status==='APPROVED'),reversals:string[]=[];for(const r of rows){const t=await one(T.TRANSACTIONS,'txn_id',r.txn_id);if(!t)throw new Error('Distribution transaction missing: '+r.txn_id);const rev=await reverseTxn(s,t.txn_id,reason);reversals.push(String(rev));await update(T.TRANSACTIONS,'txn_id',t.txn_id,{status:'REVERSED',correction_reason:reason,updated_at:now(),updated_by:s.userId});await update(T.PROFIT_DISTRIBUTION,'dist_id',r.dist_id,{status:'REVERSED',updated_at:now(),updated_by:s.userId});await notify(r.member_id,'PROFIT_REVERSAL','মুনাফা বণ্টন সংশোধন',r.amount+' টাকা মুনাফা বণ্টনের প্রভাব reverse করা হয়েছে। Ref: '+distributionId)}await update(T.PROFIT_DISTRIBUTIONS,'distribution_id',distributionId,{status:'REVERSED',distributed_amount:0,updated_at:now(),updated_by:s.userId});await rpc('nd_refresh_profit_record',{p_profit_id:h.profit_id,p_user_id:s.userId});await audit(s.userId,'REVERSE','PROFIT_DISTRIBUTION',distributionId,h,{reversalTxnIds:reversals},reason);return {ok:true,count:reversals.length,reversalTxnIds:reversals}}
async function getProfitManagementDashboard(token:string,options:A={}){const s=await sessionFromToken(token);requireProfitView(s);const rows=(await listProfitRecords(token,options)).filter((r:A)=>!['REVERSED','CANCELLED'].includes(r.STATUS)),total=round2(rows.reduce((z:number,r:A)=>z+num(r.AMOUNT),0)),distributed=round2(rows.reduce((z:number,r:A)=>z+num(r.DISTRIBUTED_AMOUNT),0)),bySource:A={},byInvestment:A={},byCategory:A={},byMonth:A={},byYear:A={};for(const r of rows){const source=r.SOURCE_NAME||r.SOURCE_ID||'Other',inv=r.INVESTMENT_NAME||r.INVESTMENT_ID||'Other',cat=r.CATEGORY||'OTHER',month=String(r.PROFIT_DATE).slice(0,7),year=String(r.PROFIT_DATE).slice(0,4);bySource[source]=num(bySource[source])+num(r.AMOUNT);byInvestment[inv]=num(byInvestment[inv])+num(r.AMOUNT);byCategory[cat]=num(byCategory[cat])+num(r.AMOUNT);byMonth[month]=num(byMonth[month])+num(r.AMOUNT);byYear[year]=num(byYear[year])+num(r.AMOUNT)}const arr=(o:A,key:string)=>Object.keys(o).sort().map(k=>({label:k,amount:round2(o[k]),[key]:k})),curMonth=monthKey(),curYear=curMonth.slice(0,4);return {totalProfit:total,distributedProfit:distributed,undistributedProfit:round2(total-distributed),monthlyProfit:round2(byMonth[curMonth]||0),yearlyProfit:round2(byYear[curYear]||0),bySource:arr(bySource,'source'),byInvestment:arr(byInvestment,'investment'),byCategory:arr(byCategory,'category'),byMonth:arr(byMonth,'month'),byYear:arr(byYear,'year'),profitRecords:rows.slice(0,100),distributions:(await listProfitDistributions(token,options)).slice(0,100)}}
async function getProfitManagementPage(token:string,options:A={}){const s=await sessionFromToken(token);requireProfitView(s);const [d,sources,investments]=await Promise.all([getProfitManagementDashboard(token,options),many(T.PROFIT_SOURCES,{},500,'created_at'),many(T.INVESTMENTS,{},500,'created_at')]);return {d,sources:upperRows(sources),investments:upperRows(investments)}}

