export const LEGACY_EXPORTED_FUNCTIONS=Object.freeze(Object.keys(LEGACY_CALLS).sort());
export async function callLegacy(fn:string,args:A[]=[]){const f=LEGACY_CALLS[String(fn||'')];if(!f)throw new Error('UNKNOWN_LEGACY_FUNCTION: '+fn);return await f(...(Array.isArray(args)?args:[]))}
